#!/usr/bin/env node/** * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ *  BANF CRM COMPLETE RECONCILIATION ENGINE * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ * *  Phase 1: Intelligent Family Grouping (co-occurrence, not surname) *  Phase 2: Complete CRM Reconciliation (9 dimensions) *  Phase 3: Interactive HTML Report for verification * *  FAMILY GROUPING STRATEGY: *    1. Explicit pairs (XLSX couple entries: "Tanmoy / Payel Banerjee") *    2. Co-occurrence in Raw Entries ("+": "Amit+Papri Saha") *    3. Family Universe v3 pre-built family groups (105 families) *    4. Shared email domain + surname within CRM *    5. Membership type inference (Couple/Family ΓåÆ 2+ adults) *    6. Family Fix Mapping (135 pre-validated family groups) *    7. Report Family Mapping (58 groups with contactId links) *    8. Google Contacts co-occurrence (same org/group) *    9. Frequency analysis: names appearing together across years * *  RECONCILIATION DIMENSIONS: *    A. Personal Info   ΓÇö name, email, phone, address, profession *    B. Family Links    ΓÇö family ID, members, type, display name *    C. Membership      ΓÇö years active, types, start dates *    D. Payments        ΓÇö amounts, categories, per year *    E. Org Roles       ΓÇö EC/BOT positions by term *    F. Volunteer       ΓÇö event participation *    G. Cultural        ΓÇö Jagriti contributions, event performers *    H. Communications  ΓÇö email threads, counts *    I. Events          ΓÇö attendance history, evite RSVPs, volunteer roles * * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */const path = require('path');const fs   = require('fs');let XLSX;try { XLSX = require('xlsx'); } catch (_) { console.error('npm install xlsx'); process.exit(1); }const ROOT = 'c:\\projects\\banf';const DATA = path.join(ROOT, 'banf1-wix', 'banf-data_ingest', 'data');const BASE_URL = 'https://banfwix.wixsite.com/banf1/_functions';const ADMIN_EMAIL = 'banfjax@gmail.com';function norm(s) { return (s || '').toLowerCase().trim(); }function titleCase(s) { return (s||'').replace(/\b\w/g, c => c.toUpperCase()).replace(/\s+/g,' ').trim(); }function stripHonorifics(s) { return s.replace(/\b(da|di|dada|didi|uncle|aunty|auntie)\b/gi, '').replace(/\s+/g,' ').trim(); }function stripParens(s) { return s.replace(/\(.*?\)/g, '').trim(); }async function apiFetch(endpoint, method = 'GET', body = null) {    const { default: fetch } = await import('node-fetch');    const opts = { method, headers: { 'Content-Type': 'application/json', 'x-user-email': ADMIN_EMAIL } };    if (body) opts.body = JSON.stringify(body);    const r = await fetch(`${BASE_URL}/${endpoint}`, opts);    return r.json();}function readJSON(fp) {    try { let r = fs.readFileSync(fp, 'utf8').replace(/^\uFEFF/, ''); return JSON.parse(r); }    catch(e) { console.warn(`  [WARN] ${fp}: ${e.message}`); return null; }}function readXLSXSheets(fp) {    try { const wb = XLSX.readFile(fp); const r = {}; for (const s of wb.SheetNames) r[s] = XLSX.utils.sheet_to_json(wb.Sheets[s], { defval: '' }); return r; }    catch(e) { console.warn(`  [WARN] ${fp}: ${e.message}`); return {}; }}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// PHASE 1: INTELLIGENT FAMILY GROUPING// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉclass FamilyGraph {    constructor() {        this.nodes = new Map();      // email ΓåÆ person record        this.edges = new Map();      // edge key ΓåÆ { a, b, weight, evidence[] }        this.families = new Map();   // familyId ΓåÆ { members, evidence[], displayName, type }  (family NETWORK)        this.households = new Map(); // householdId ΓåÆ { members, type, displayName, spouseEvidence[], inferredKids }    }    addPerson(email, data) {        if (!email) return;        const key = norm(email);        if (!this.nodes.has(key)) {            this.nodes.set(key, { email: key, firstName: '', lastName: '', displayName: '', phone: '', ...data });        } else {            const existing = this.nodes.get(key);            for (const [k, v] of Object.entries(data)) {                if (v && (!existing[k] || existing[k] === key)) existing[k] = v;            }        }    }    addEdge(emailA, emailB, weight, evidenceType, detail = '') {        const a = norm(emailA), b = norm(emailB);        if (!a || !b || a === b) return;        const key = [a, b].sort().join('|');        if (!this.edges.has(key)) {            this.edges.set(key, { a, b, weight: 0, evidence: [] });        }        const edge = this.edges.get(key);        edge.weight += weight;        edge.evidence.push({ type: evidenceType, detail, weight });    }    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    // LAYER 1: HOUSEHOLD UNITS (Membership-Based)    //   Payment for membership is the MOST important marker.    //   Phase 1: Membership XLSX entries = primary households (~82 units)    //   Phase 2: Spouse edge detection for remaining members    //   Phase 3: Individual fallback    //   Phase 4: Kid inference from event data    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    buildHouseholds(eventData, membershipRows, resolveFunc) {        this.households = new Map();        const assigned = new Set();        let hhCounter = 1;        // ΓöÇΓöÇ PHASE 1: Membership XLSX = Primary household signal ΓöÇΓöÇ        // Each XLSX row = 1 paid membership unit (household).        console.log('    Phase 1: Membership XLSX ΓåÆ primary households...');        let xlsxHH = 0;        if (membershipRows && resolveFunc) {            for (const row of membershipRows) {                const rawName = (row.Name || '').trim();                const category = (row.Category || '').trim();                const amount = parseFloat(row.Amount) || 0;                if (!rawName) continue;                const nameParts = rawName.split(/[\/&+]/).map(p => stripParens(stripHonorifics(p)).trim()).filter(Boolean);                const lastPart = nameParts[nameParts.length - 1];                const lastWords = lastPart.split(/\s+/);                const sharedSurname = lastWords.length >= 2 ? lastWords[lastWords.length - 1] : '';                const resolvedEmails = [];                for (let np of nameParts) {                    const words = np.split(/\s+/).filter(Boolean);                    if (words.length === 1 && sharedSurname && norm(words[0]) !== norm(sharedSurname)) {                        np = `${words[0]} ${sharedSurname}`;                    }                    const nw = norm(np).split(/\s+/);                    const email = resolveFunc(nw[0], nw.slice(1).join(' '));                    if (email && this.nodes.has(email) && !assigned.has(email)) resolvedEmails.push(email);                }                if (resolvedEmails.length === 0) continue;                let hhType = 'individual';                const catLower = category.toLowerCase();                if (catLower.includes('family')) hhType = 'family';                else if (catLower.includes('couple')) hhType = 'couple';                else if (catLower.includes('student')) hhType = 'individual';                else if (resolvedEmails.length >= 2) hhType = 'couple';                const hhId = `HH-${String(hhCounter++).padStart(3, '0')}`;                const memberList = resolvedEmails.map(e => this.nodes.get(e)).filter(Boolean);                const surnames = [...new Set(memberList.map(m => norm(m.lastName)).filter(Boolean))];                this.households.set(hhId, {                    householdId: hhId,                    members: new Set(resolvedEmails),                    memberList,                    type: hhType,                    displayName: this.buildFamilyDisplayName(memberList, surnames),                    surnames,                    spouseEvidence: [{ type: 'membership_xlsx_payment', detail: `${category}: "${rawName}" ($${amount})`, weight: 15 }],                    totalSpouseWeight: 15,                    inferredKids: 0,                    inferredAdults: resolvedEmails.length,                    membershipCategory: category,                    membershipAmount: amount,                    membershipRawName: rawName,                    yearActive: ['2025-26'],                    lastUpdated: new Date().toISOString()                });                resolvedEmails.forEach(e => assigned.add(e));                xlsxHH++;            }        }        console.log(`      ΓåÆ ${xlsxHH} households from membership XLSX`);        // ΓöÇΓöÇ PHASE 2: Spouse edges for remaining members ΓöÇΓöÇ        console.log('    Phase 2: Spouse edges for unassigned members...');        const SPOUSE_TYPES = new Set(['raw_entry_cooccurrence', 'membership_xlsx_couple', 'cross_year_frequency']);        const spouseEdges = [];        for (const [, edge] of this.edges) {            let spouseWeight = 0;            const spouseEvidence = [];            for (const ev of edge.evidence) {                if (SPOUSE_TYPES.has(ev.type)) { spouseWeight += ev.weight; spouseEvidence.push(ev); }                else if (ev.type === 'family_fix_mapping' && ev.detail.toLowerCase().includes('couple')) { spouseWeight += ev.weight; spouseEvidence.push(ev); }            }            if (spouseWeight > 0) spouseEdges.push({ a: edge.a, b: edge.b, spouseWeight, spouseEvidence });        }        spouseEdges.sort((a, b) => b.spouseWeight - a.spouseWeight);        let edgeHH = 0;        for (const se of spouseEdges) {            const aIn = assigned.has(se.a), bIn = assigned.has(se.b);            // Add unassigned spouse to an existing 1-member household            if (aIn && !bIn) {                for (const [, hh] of this.households) {                    if (hh.members.has(se.a) && hh.members.size < 2) {                        hh.members.add(se.b); const mB = this.nodes.get(se.b);                        if (mB) hh.memberList.push(mB);                        hh.spouseEvidence.push(...se.spouseEvidence);                        hh.totalSpouseWeight += se.spouseWeight;                        hh.inferredAdults = hh.members.size;                        if (hh.type === 'individual') hh.type = 'couple';                        hh.surnames = [...new Set(hh.memberList.map(m => norm(m.lastName)).filter(Boolean))];                        hh.displayName = this.buildFamilyDisplayName(hh.memberList, hh.surnames);                        assigned.add(se.b); edgeHH++; break;                    }                }                continue;            }            if (!aIn && bIn) {                for (const [, hh] of this.households) {                    if (hh.members.has(se.b) && hh.members.size < 2) {                        hh.members.add(se.a); const mA = this.nodes.get(se.a);                        if (mA) hh.memberList.push(mA);                        hh.spouseEvidence.push(...se.spouseEvidence);                        hh.totalSpouseWeight += se.spouseWeight;                        hh.inferredAdults = hh.members.size;                        if (hh.type === 'individual') hh.type = 'couple';                        hh.surnames = [...new Set(hh.memberList.map(m => norm(m.lastName)).filter(Boolean))];                        hh.displayName = this.buildFamilyDisplayName(hh.memberList, hh.surnames);                        assigned.add(se.a); edgeHH++; break;                    }                }                continue;            }            // Neither assigned: new couple household            if (!aIn && !bIn) {                const hhId = `HH-${String(hhCounter++).padStart(3, '0')}`;                const mA = this.nodes.get(se.a), mB = this.nodes.get(se.b);                const surnames = [...new Set([norm(mA?.lastName), norm(mB?.lastName)].filter(Boolean))];                this.households.set(hhId, {                    householdId: hhId, members: new Set([se.a, se.b]),                    memberList: [mA, mB].filter(Boolean), type: 'couple',                    displayName: this.buildFamilyDisplayName([mA, mB].filter(Boolean), surnames),                    surnames, spouseEvidence: se.spouseEvidence, totalSpouseWeight: se.spouseWeight,                    inferredKids: 0, inferredAdults: 2,                    membershipCategory: '', membershipAmount: 0, membershipRawName: '',                    yearActive: [], lastUpdated: new Date().toISOString()                });                assigned.add(se.a); assigned.add(se.b); edgeHH++;            }        }        console.log(`      ΓåÆ ${edgeHH} additional from spouse edges`);        // ΓöÇΓöÇ PHASE 3: Individual fallback ΓöÇΓöÇ        for (const email of this.nodes.keys()) {            if (assigned.has(email)) continue;            const hhId = `HH-${String(hhCounter++).padStart(3, '0')}`;            const m = this.nodes.get(email);            this.households.set(hhId, {                householdId: hhId, members: new Set([email]),                memberList: [m].filter(Boolean), type: 'individual',                displayName: m ? `${m.firstName} ${m.lastName}`.trim() || email : email,                surnames: [norm(m?.lastName)].filter(Boolean),                spouseEvidence: [], totalSpouseWeight: 0,                inferredKids: 0, inferredAdults: 1,                membershipCategory: '', membershipAmount: 0, membershipRawName: '',                yearActive: [], lastUpdated: new Date().toISOString()            });        }        // ΓöÇΓöÇ PHASE 4: Kid inference from events ΓöÇΓöÇ        if (eventData) {            for (const [, hh] of this.households) {                let maxKids = 0;                for (const email of hh.members) {                    for (const ev of (eventData[email] || [])) {                        if (ev.kids && parseInt(ev.kids) > maxKids) maxKids = parseInt(ev.kids);                    }                }                hh.inferredKids = maxKids;                if (maxKids > 0 && hh.type === 'couple') hh.type = 'family';            }        }        const nonInd = [...this.households.values()].filter(h => h.type !== 'individual');        console.log(`    ΓåÆ Households: ${this.households.size} total (${nonInd.length} couples/families, ${this.households.size - nonInd.length} individuals)`);        return this.households;    }    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    // LAYER 2: FAMILY NETWORKS (Relationships)    //   Broader family connections across all evidence types.    //   Uses Union-Find but with MAX GROUP SIZE cap to prevent    //   runaway chains. Oversized groups are decomposed by raising    //   the internal edge threshold until sub-groups are Γëñ maxSize.    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    buildFamilies(threshold = 3, maxSize = 6) {        const parent = {};        const find = (x) => { if (parent[x] !== x) parent[x] = find(parent[x]); return parent[x]; };        const union = (x, y) => { parent[find(x)] = find(y); };        // Initialize        for (const email of this.nodes.keys()) parent[email] = email;        // Union edges above threshold        for (const [key, edge] of this.edges) {            if (edge.weight >= threshold) {                union(edge.a, edge.b);            }        }        // Collect raw groups        const rawGroups = {};        for (const email of this.nodes.keys()) {            const root = find(email);            if (!rawGroups[root]) rawGroups[root] = new Set();            rawGroups[root].add(email);        }        // Decompose oversized groups, keep small ones as-is        const finalGroups = [];        for (const [root, members] of Object.entries(rawGroups)) {            if (members.size <= maxSize) {                finalGroups.push(members);            } else {                // Progressively raise threshold to break chains                const subGroups = this._decomposeGroup(members, threshold, maxSize);                finalGroups.push(...subGroups);            }        }        // Build family records        let fidCounter = 1;        for (const members of finalGroups) {            if (members.size < 1) continue;            const fid = `RFAM-${String(fidCounter++).padStart(3, '0')}`;            const memberList = [...members].map(e => this.nodes.get(e));            const surnames = [...new Set(memberList.map(m => norm(m.lastName)).filter(Boolean))];            const displayName = this.buildFamilyDisplayName(memberList, surnames);            const type = members.size >= 3 ? 'family' : members.size === 2 ? 'couple' : 'individual';            // Collect evidence for why these are grouped            const evidence = [];            for (const [key, edge] of this.edges) {                if (members.has(edge.a) && members.has(edge.b)) {                    evidence.push(...edge.evidence);                }            }            this.families.set(fid, {                familyId: fid,                members,                memberList,                displayName,                type,                surnames,                evidence,                totalWeight: evidence.reduce((s, e) => s + e.weight, 0)            });        }        return this.families;    }    // Break an oversized group by raising the internal edge threshold    _decomposeGroup(members, baseThreshold, maxSize) {        // Collect internal edges        const internalEdges = [];        for (const [key, edge] of this.edges) {            if (members.has(edge.a) && members.has(edge.b)) {                internalEdges.push(edge);            }        }        // Try progressively higher thresholds        for (let t = baseThreshold + 5; t <= 60; t += 3) {            const parent = {};            const find = (x) => { if (parent[x] !== x) parent[x] = find(parent[x]); return parent[x]; };            const union = (x, y) => { parent[find(x)] = find(y); };            for (const email of members) parent[email] = email;            for (const edge of internalEdges) {                if (edge.weight >= t) union(edge.a, edge.b);            }            const subGroups = {};            for (const email of members) {                const root = find(email);                if (!subGroups[root]) subGroups[root] = new Set();                subGroups[root].add(email);            }            const groups = Object.values(subGroups);            if (groups.every(g => g.size <= maxSize)) {                console.log(`    ΓåÆ Decomposed group of ${members.size} at threshold ${t} into ${groups.length} sub-groups (sizes: ${groups.map(g => g.size).sort((a,b) => b-a).join(', ')})`);                return groups;            }        }        // Last resort: each person becomes their own group        console.log(`    ΓåÆ Could not decompose group of ${members.size}, splitting to individuals`);        return [...members].map(e => new Set([e]));    }    buildFamilyDisplayName(members, surnames) {        if (members.length === 1) {            return `${members[0].firstName} ${members[0].lastName}`.trim() || members[0].email;        }        const firstNames = members.map(m => m.firstName).filter(Boolean);        const primarySurname = surnames[0] || '';        if (firstNames.length <= 3) {            return `${firstNames.join(' & ')} ${titleCase(primarySurname)}`.trim();        }        return `${titleCase(primarySurname)} Family (${members.length})`;    }}async function buildFamilyGraph(sources) {    const graph = new FamilyGraph();    // ΓöÇΓöÇ Register all known persons ΓöÇΓöÇ    console.log('  Building person registry...');    // From CRM    for (const m of sources.crmMembers) {        if (!m.email) continue;        graph.addPerson(m.email, {            firstName: norm(m.firstName) === norm(m.email) ? '' : m.firstName,            lastName: m.lastName, displayName: m.displayName, phone: m.phone        });    }    // From Google Contacts    for (const c of sources.googleContacts) {        if (!c.email) continue;        graph.addPerson(c.email, {            firstName: c.firstName, lastName: c.lastName, displayName: c.displayName, phone: c.phone        });    }    // From member audit    for (const m of sources.memberAudit) {        if (!m.email) continue;        graph.addPerson(m.email, {            firstName: norm(m.firstName) === norm(m.email) ? '' : m.firstName,            lastName: m.lastName, displayName: m.displayName, phone: m.phone        });    }    console.log(`  ΓåÆ ${graph.nodes.size} persons registered`);    // ΓöÇΓöÇ Build email lookup indices ΓöÇΓöÇ    const emailByFirstLast = {};   // "first|last" ΓåÆ [emails]    const emailByFirst = {};        // "first" ΓåÆ [emails]    for (const [email, person] of graph.nodes) {        const f = norm(person.firstName), l = norm(person.lastName);        if (f && l) {            const key = `${f}|${l}`;            (emailByFirstLast[key] = emailByFirstLast[key] || []).push(email);        }        if (f) (emailByFirst[f] = emailByFirst[f] || []).push(email);    }    function resolveEmail(firstName, lastName) {        const f = norm(firstName), l = norm(lastName);        if (f && l) {            const exact = emailByFirstLast[`${f}|${l}`];            if (exact && exact.length === 1) return exact[0];            // Prefix match on last name            for (const [key, emails] of Object.entries(emailByFirstLast)) {                const [kf, kl] = key.split('|');                if (kf === f && l.length >= 3 && kl.startsWith(l.substring(0, 4))) return emails[0];                if (kf === f && kl.length >= 3 && l.startsWith(kl.substring(0, 4))) return emails[0];            }        }        if (f) {            const candidates = emailByFirst[f];            if (candidates && candidates.length === 1) return candidates[0];        }        return null;    }    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    // EVIDENCE LAYER 1: Family Universe v3 (Pre-built families)    // WEIGHT: 10 (high confidence ΓÇö curated data)    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    console.log('  Evidence Layer 1: Family Universe v3...');    let edgesAdded = 0;    for (const fm of sources.familyMembers) {        const fid = fm['Family ID'];        // Find all members in this family        const familyMates = sources.familyMembers.filter(m => m['Family ID'] === fid && m !== fm);        const myEmail = resolveEmail(fm['First Name'], fm['Last Name']);        if (!myEmail) continue;        for (const mate of familyMates) {            const mateEmail = resolveEmail(mate['First Name'], mate['Last Name']);            if (mateEmail && myEmail !== mateEmail) {                graph.addEdge(myEmail, mateEmail, 10, 'family_universe_v3',                    `Same family ${fid}: ${fm['First Name']} + ${mate['First Name']} ${fm['Primary Surname']}`);                edgesAdded++;            }        }    }    console.log(`      ΓåÆ ${edgesAdded} edges from Family Universe`);    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    // EVIDENCE LAYER 2: Raw Entries co-occurrence ("+" notation)    // WEIGHT: 8 (strong ΓÇö names explicitly paired)    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    console.log('  Evidence Layer 2: Raw Entries co-occurrence...');    edgesAdded = 0;    for (const raw of sources.rawEntries) {        const entry = raw['Name Entry'] || '';        if (!entry.includes('+')) continue;        const parts = entry.split('+').map(p => p.trim());        if (parts.length < 2) continue;        // Last part usually has the shared surname        const lastPart = parts[parts.length - 1];        const lastWords = lastPart.split(/\s+/);        const sharedSurname = lastWords.length >= 2 ? lastWords[lastWords.length - 1] : '';        const emails = [];        for (let p of parts) {            p = stripParens(stripHonorifics(p)).trim();            const words = p.split(/\s+/).filter(Boolean);            const firstName = words[0];            const lastName = words.length >= 2 ? words.slice(1).join(' ') : sharedSurname;            const email = resolveEmail(firstName, lastName);            if (email) emails.push(email);        }        // All pairs in this entry are family        for (let i = 0; i < emails.length; i++) {            for (let j = i + 1; j < emails.length; j++) {                graph.addEdge(emails[i], emails[j], 8, 'raw_entry_cooccurrence',                    `Co-occur in raw entry "${entry}" (${raw.Year})`);                edgesAdded++;            }        }    }    console.log(`      ΓåÆ ${edgesAdded} edges from Raw Entries`);    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    // EVIDENCE LAYER 3: Membership XLSX couples (/ or & split)    // WEIGHT: 8 (strong ΓÇö explicit couples in membership)    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    console.log('  Evidence Layer 3: Membership XLSX couples...');    edgesAdded = 0;    for (const m of sources.membership2526) {        const rawName = (m.Name || '').trim();        if (!rawName.match(/[\/&]/)) continue;        const parts = rawName.split(/[\/&]/).map(p => stripParens(stripHonorifics(p)).trim()).filter(Boolean);        const lastPart = parts[parts.length - 1];        const lastWords = lastPart.split(/\s+/);        const sharedSurname = lastWords.length >= 2 ? lastWords[lastWords.length - 1] : '';        const emails = [];        for (let p of parts) {            const words = p.split(/\s+/).filter(Boolean);            const firstName = words[0];            const lastName = words.length >= 2 ? words.slice(1).join(' ') : sharedSurname;            const email = resolveEmail(firstName, lastName);            if (email) emails.push(email);        }        for (let i = 0; i < emails.length; i++) {            for (let j = i + 1; j < emails.length; j++) {                graph.addEdge(emails[i], emails[j], 8, 'membership_xlsx_couple',                    `Couple in XLSX: "${rawName}" (${m.Category})`);                edgesAdded++;            }        }    }    console.log(`      ΓåÆ ${edgesAdded} edges from Membership XLSX`);    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    // EVIDENCE LAYER 4: Family Fix Mapping (validated groupings)    // WEIGHT: 12 (highest ΓÇö manually validated)    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    console.log('  Evidence Layer 4: Family Fix Mapping...');    edgesAdded = 0;    for (const fam of sources.familyFixMapping) {        const members = fam.members || [];        const emails = members.map(m => norm(m.email)).filter(Boolean);        for (let i = 0; i < emails.length; i++) {            for (let j = i + 1; j < emails.length; j++) {                graph.addEdge(emails[i], emails[j], 12, 'family_fix_mapping',                    `Family Fix: "${fam.displayName}" (${fam.familyType})`);                edgesAdded++;            }        }    }    console.log(`      ΓåÆ ${edgesAdded} edges from Family Fix Mapping`);    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    // EVIDENCE LAYER 5: Report Family Mapping (58 families)    // WEIGHT: 10 (high ΓÇö from CRM report)    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    console.log('  Evidence Layer 5: Report Family Mapping...');    edgesAdded = 0;    for (const fam of sources.reportFamilyMapping) {        const members = fam.members || [];        const emails = members.map(m => norm(m.email)).filter(Boolean);        for (let i = 0; i < emails.length; i++) {            for (let j = i + 1; j < emails.length; j++) {                graph.addEdge(emails[i], emails[j], 10, 'report_family_mapping',                    `Report Family: "${fam.display_name}" (${fam.primary_surname})`);                edgesAdded++;            }        }    }    console.log(`      ΓåÆ ${edgesAdded} edges from Report Family Mapping`);    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    // EVIDENCE LAYER 6: CRM existing familyId groupings    // WEIGHT: 6 (moderate ΓÇö may have errors from surname-based)    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    console.log('  Evidence Layer 6: CRM familyId groupings...');    edgesAdded = 0;    const crmFamilyMap = {};    for (const m of sources.crmMembers) {        if (!m.email || !m.familyId) continue;        (crmFamilyMap[m.familyId] = crmFamilyMap[m.familyId] || []).push(norm(m.email));    }    for (const emails of Object.values(crmFamilyMap)) {        for (let i = 0; i < emails.length; i++) {            for (let j = i + 1; j < emails.length; j++) {                graph.addEdge(emails[i], emails[j], 6, 'crm_existing_family',                    `CRM same familyId`);                edgesAdded++;            }        }    }    console.log(`      ΓåÆ ${edgesAdded} edges from CRM familyId`);    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    // EVIDENCE LAYER 7: Shared surname + email domain    // WEIGHT: 4 (weak ΓÇö can be coincidence, but useful signal)    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    console.log('  Evidence Layer 7: Shared surname + email domain...');    edgesAdded = 0;    const bySurnameDomain = {};    for (const [email, person] of graph.nodes) {        const surname = norm(person.lastName);        const domain = email.split('@')[1] || '';        if (surname && surname.length >= 3 && !['gmail.com', 'yahoo.com', 'hotmail.com', 'aol.com', 'outlook.com', 'msn.com', 'icloud.com'].includes(domain)) {            const key = `${surname}|${domain}`;            (bySurnameDomain[key] = bySurnameDomain[key] || []).push(email);        }    }    for (const emails of Object.values(bySurnameDomain)) {        if (emails.length >= 2 && emails.length <= 5) {            for (let i = 0; i < emails.length; i++) {                for (let j = i + 1; j < emails.length; j++) {                    graph.addEdge(emails[i], emails[j], 4, 'surname_domain',                        `Same surname + custom email domain`);                    edgesAdded++;                }            }        }    }    console.log(`      ΓåÆ ${edgesAdded} edges from surname+domain`);    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    // EVIDENCE LAYER 8: Cross-year frequency analysis    // WEIGHT: 5 per year (strong if consistent across years)    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    console.log('  Evidence Layer 8: Cross-year frequency analysis...');    edgesAdded = 0;    // Group raw entries by year and find names that consistently appear together    const yearlyCooccurrence = {};    for (const raw of sources.rawEntries) {        const year = raw.Year;        const entry = raw['Name Entry'] || '';        // Extract all first names from entries like "Amit+Papri Saha"        const names = entry.split(/[+\/&,]/).map(p => norm(stripParens(stripHonorifics(p.trim())).split(/\s+/)[0])).filter(Boolean);        for (const name of names) {            const key = `${year}|${name}`;            if (!yearlyCooccurrence[key]) yearlyCooccurrence[key] = new Set();            // The "family unit" for this year includes all names in the same entry            names.forEach(n => { if (n !== name) yearlyCooccurrence[key].add(n); });        }    }    // Names that appear TOGETHER in 2+ years are almost certainly family    const pairYearCount = {};    for (const [key, partners] of Object.entries(yearlyCooccurrence)) {        const [year, name] = key.split('|');        for (const partner of partners) {            const pairKey = [name, partner].sort().join('~');            if (!pairYearCount[pairKey]) pairYearCount[pairKey] = new Set();            pairYearCount[pairKey].add(year);        }    }    for (const [pairKey, years] of Object.entries(pairYearCount)) {        if (years.size >= 2) {            const [nameA, nameB] = pairKey.split('~');            // Resolve to emails            const emailsA = emailByFirst[nameA] || [];            const emailsB = emailByFirst[nameB] || [];            if (emailsA.length === 1 && emailsB.length === 1 && emailsA[0] !== emailsB[0]) {                graph.addEdge(emailsA[0], emailsB[0], 5 * years.size, 'cross_year_frequency',                    `Co-occur ${years.size} years: ${[...years].join(', ')}`);                edgesAdded++;            }        }    }    console.log(`      ΓåÆ ${edgesAdded} edges from cross-year frequency`);    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    // EVIDENCE LAYER 9: Membership type inference    // WEIGHT: 3 (supportive ΓÇö Couple/Family type implies 2+ adults)    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    console.log('  Evidence Layer 9: Membership type inference...');    // For members in CRM with "couple" or "family" familyType but no family link,    // find the most likely partner by surname + shared year    // (This is a weaker signal, only adds to existing evidence)    console.log(`\n  TOTAL: ${graph.nodes.size} persons, ${graph.edges.size} edges`);    return graph;}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// PHASE 2: COMPLETE CRM RECONCILIATION// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉfunction reconcileMembers(sources, familyGraph) {    const universe = new Map(); // email ΓåÆ unified record    function getOrCreate(email) {        const key = norm(email);        if (!key || !key.includes('@')) return null;        if (!universe.has(key)) {            universe.set(key, {                email: key,                // A. Personal                firstName: '', lastName: '', displayName: '',                phone: '', phone2: '', address: '', city: '', state: '', zip: '',                gender: '', profession: '', employer: '', education: '', dateOfBirth: '',                // B1. Household (Membership Unit ΓÇö payment is primary signal)                householdId: '', householdType: '', householdDisplayName: '', householdMembers: [],                householdRole: 'primary', householdEvidence: [], inferredKids: 0,                householdMembershipCategory: '', householdMembershipAmount: 0, householdYearActive: [],                // B2. Family Network (Relationships ΓÇö broader connections)                familyId: '', familyType: '', familyDisplayName: '', familyMembers: [],                familyEvidence: [],                // C. Membership                memberId: '', memberSince: '', memberType: 'adult',                membershipYears: new Set(), membershipTypes: new Set(),                isActive: true, isECMember: false, isBOTMember: false,                // D. Payments                paymentRecords: [], totalPaid: 0,                // E. Org Roles                orgRoles: [],                // F. Volunteer                volunteerRecords: [],                // G. Cultural                jagritiContributions: [], culturalParticipation: [],                // H. Communications                communications: 0, lastCommDate: '',                // I. Events                eventAttendance: [],  // { eventName, eventDate, rsvp, adults, kids, totalAttendees, dietary, amount, source }                volunteerEvents: [],  // { eventName, role, source }                // Meta                importSources: new Set(),                reconciliation: { personal: [], family: [], membership: [], payment: [], orgRole: [], volunteer: [], cultural: [], communication: [], events: [] },                issues: [],                raw: {}            });        }        return universe.get(key);    }    function merge(rec, field, value, source) {        if (!value || value === '' || value === 'N/A') return;        const v = String(value).trim();        const old = rec[field];        if (!old || old === '' || old === rec.email) {            rec[field] = v;            rec.reconciliation.personal.push({ field, value: v, source, action: 'set' });        } else if (norm(old) !== norm(v)) {            // Conflict ΓÇö log it            rec.reconciliation.personal.push({ field, oldValue: old, newValue: v, source, action: 'conflict' });        }    }    // ΓöÇΓöÇ SOURCE 1: Live CRM ΓöÇΓöÇ    console.log('  [A] Reconciling Personal Info from CRM...');    for (const m of sources.crmMembers) {        if (!m.email) continue;        const rec = getOrCreate(m.email);        if (!rec) continue;        merge(rec, 'firstName', norm(m.firstName) === norm(m.email) ? '' : m.firstName, 'crm');        merge(rec, 'lastName', m.lastName, 'crm');        merge(rec, 'displayName', m.displayName, 'crm');        merge(rec, 'phone', m.phone, 'crm');        merge(rec, 'phone2', m.phone2, 'crm');        merge(rec, 'address', m.address, 'crm');        merge(rec, 'city', m.city, 'crm');        merge(rec, 'state', m.state, 'crm');        merge(rec, 'zip', m.zip || m.zipCode, 'crm');        merge(rec, 'gender', m.gender, 'crm');        merge(rec, 'profession', m.profession, 'crm');        merge(rec, 'employer', m.employer, 'crm');        merge(rec, 'memberId', m.memberId, 'crm');        merge(rec, 'memberSince', m.memberSince, 'crm');        merge(rec, 'dateOfBirth', m.dateOfBirth, 'crm');        rec.memberType = m.memberType || rec.memberType;        rec.isActive = m.isActive !== false;        rec.isECMember = rec.isECMember || m.isECMember;        rec.isBOTMember = rec.isBOTMember || m.isBOTMember;        if (m.membershipType) rec.membershipTypes.add(m.membershipType);        rec.importSources.add('crm');        rec.raw.crm = m;    }    // ΓöÇΓöÇ SOURCE 2: Google Contacts ΓöÇΓöÇ    console.log('  [A] Reconciling Personal Info from Google Contacts...');    for (const c of sources.googleContacts) {        if (!c.email) continue;        const rec = getOrCreate(c.email);        if (!rec) continue;        merge(rec, 'firstName', c.firstName, 'google_contacts');        merge(rec, 'lastName', c.lastName, 'google_contacts');        merge(rec, 'displayName', c.displayName, 'google_contacts');        merge(rec, 'phone', c.phone, 'google_contacts');        rec.importSources.add('google_contacts');    }    // ΓöÇΓöÇ SOURCE 3: Member Audit ΓöÇΓöÇ    console.log('  [A] Reconciling Personal Info from Member Audit...');    for (const m of sources.memberAudit) {        if (!m.email) continue;        const rec = getOrCreate(m.email);        if (!rec) continue;        merge(rec, 'firstName', norm(m.firstName) === norm(m.email) ? '' : m.firstName, 'member_audit');        merge(rec, 'lastName', m.lastName, 'member_audit');        merge(rec, 'phone', m.phone, 'member_audit');        merge(rec, 'address', m.address, 'member_audit');        merge(rec, 'city', m.city, 'member_audit');        merge(rec, 'state', m.state, 'member_audit');        merge(rec, 'zip', m.zip || m.zipCode, 'member_audit');        merge(rec, 'gender', m.gender, 'member_audit');        merge(rec, 'profession', m.profession, 'member_audit');        merge(rec, 'employer', m.employer, 'member_audit');        merge(rec, 'education', m.education, 'member_audit');        merge(rec, 'dateOfBirth', m.dateOfBirth, 'member_audit');        rec.importSources.add('member_audit');    }    // ΓöÇΓöÇ SOURCE 4: Admin Report (EC Roles) ΓöÇΓöÇ    console.log('  [E] Reconciling Org Roles from Admin Report...');    if (sources.adminReport && sources.adminReport.report) {        for (const term of (sources.adminReport.report.ecTerms || [])) {            for (const c of (term.contacts || [])) {                if (!c.email) continue;                const rec = getOrCreate(c.email);                if (!rec) continue;                const cName = c.name || c.firstName || '';                merge(rec, 'firstName', cName.split(' ')[0], 'admin_report');                merge(rec, 'lastName', cName.split(' ').slice(1).join(' '), 'admin_report');                if (c.phone) merge(rec, 'phone', c.phone, 'admin_report');                for (const role of (c.roles || [])) {                    const roleName = typeof role === 'string' ? role : role.role || JSON.stringify(role);                    rec.orgRoles.push({ term: term.term, role: roleName, source: 'admin_report' });                    rec.reconciliation.orgRole.push({ term: term.term, role: roleName, source: 'admin_report' });                }                if (c.categories && c.categories.includes('EC')) rec.isECMember = true;                if (c.categories && c.categories.includes('BOT')) rec.isBOTMember = true;                rec.importSources.add('admin_report');            }        }    }    // ΓöÇΓöÇ SOURCE 5: Membership 2025-26 XLSX (Payments + Membership) ΓöÇΓöÇ    console.log('  [C,D] Reconciling Membership & Payments from XLSX...');    const emailByFirstMap = {};    for (const [email, rec] of universe) {        const f = norm(rec.firstName);        if (f) (emailByFirstMap[f] = emailByFirstMap[f] || []).push({ email, rec });    }    const emailByFullMap = {};    for (const [email, rec] of universe) {        const full = `${norm(rec.firstName)} ${norm(rec.lastName)}`.trim();        if (full && full !== ' ') emailByFullMap[full] = email;    }    let xlsxMatched = 0, xlsxUnmatched = 0;    sources._unmatchedMembership = [];    for (const m of sources.membership2526) {        const rawName = (m.Name || '').trim();        const category = m.Category || '';        const amount = m.Amount || 0;        if (!rawName) continue;        const nameParts = rawName.split(/[\/&]/).map(p => stripParens(stripHonorifics(p)).trim()).filter(Boolean);        const lastPart = nameParts[nameParts.length - 1];        const lastWords = lastPart.split(/\s+/);        const sharedSurname = lastWords.length >= 2 ? lastWords[lastWords.length - 1] : '';        let anyMatched = false;        for (let np of nameParts) {            const words = np.split(/\s+/).filter(Boolean);            if (words.length === 1 && sharedSurname && norm(words[0]) !== norm(sharedSurname)) {                np = `${words[0]} ${sharedSurname}`;            }            const cleaned = norm(np);            let matchEmail = emailByFullMap[cleaned];            if (!matchEmail) {                // Try first name only (unique)                const first = cleaned.split(/\s+/)[0];                const last = cleaned.split(/\s+/).slice(1).join(' ');                // Prefix match                if (first && last && last.length >= 3) {                    for (const [full, em] of Object.entries(emailByFullMap)) {                        const fp = full.split(' ');                        if (fp[0] === first && fp.slice(1).join(' ').startsWith(last.substring(0, 4))) { matchEmail = em; break; }                        if (fp[0] === first && last.startsWith(fp.slice(1).join(' ').substring(0, 4))) { matchEmail = em; break; }                    }                }                if (!matchEmail && first && emailByFirstMap[first] && emailByFirstMap[first].length === 1) {                    matchEmail = emailByFirstMap[first][0].email;                }            }            if (matchEmail) {                const rec = universe.get(matchEmail);                if (rec) {                    rec.membershipYears.add('2025-26');                    rec.membershipTypes.add(category);                    const payAmt = amount / nameParts.length;                    rec.paymentRecords.push({ year: '2025-26', category, amount: payAmt, source: 'membership_xlsx', rawName });                    rec.totalPaid += payAmt;                    rec.reconciliation.payment.push({ year: '2025-26', category, amount: payAmt, source: 'membership_xlsx' });                    rec.reconciliation.membership.push({ year: '2025-26', type: category, source: 'membership_xlsx' });                    rec.importSources.add('membership_2526');                    anyMatched = true;                }            }        }        if (anyMatched) xlsxMatched++; else { xlsxUnmatched++; sources._unmatchedMembership.push({ name: rawName, category, amount }); }    }    sources._xlsxMatched = xlsxMatched;    sources._xlsxUnmatched = xlsxUnmatched;    console.log(`      ΓåÆ XLSX matched: ${xlsxMatched}/${xlsxMatched + xlsxUnmatched}, unmatched: ${xlsxUnmatched}`);    // ΓöÇΓöÇ SOURCE 6: Family Universe Yearly Membership (historical) ΓöÇΓöÇ    console.log('  [C] Reconciling Historical Membership from Family Universe...');    for (const ym of sources.yearlyMembership) {        const memberNames = (ym.Members || '').split(',').map(n => norm(n.trim())).filter(Boolean);        const years = ['2022-23', '2023-24', '2024-25', '2025-26'];        for (const name of memberNames) {            const candidates = emailByFirstMap[name] || [];            for (const { email, rec } of candidates) {                for (const yr of years) {                    if (ym[yr] === 'Γ£ô' || ym[yr] === true) {                        rec.membershipYears.add(yr);                        rec.reconciliation.membership.push({ year: yr, type: 'historical', source: 'family_universe_yearly' });                    }                }            }        }    }    // ΓöÇΓöÇ SOURCE 7: CRM Comprehensive (payments, comms, issues) ΓöÇΓöÇ    console.log('  [D,H] Reconciling Payments & Communications from CRM Comprehensive...');    for (const m of sources.crmComprehensive) {        if (!m.email) continue;        const rec = universe.get(norm(m.email));        if (!rec) continue;        if (m.communications > rec.communications) rec.communications = m.communications;        rec.reconciliation.communication.push({ count: m.communications, source: 'crm_comprehensive' });        if (m.payments > 0) rec.reconciliation.payment.push({ crmPayments: m.payments, source: 'crm_comprehensive' });        if (m.orgRoles > 0) rec.reconciliation.orgRole.push({ crmOrgRoles: m.orgRoles, source: 'crm_comprehensive' });        rec.importSources.add('crm_comprehensive');    }    // ΓöÇΓöÇ SOURCE 8: Jagriti Contributors ΓöÇΓöÇ    console.log('  [G] Reconciling Cultural Participation from Jagriti...');    // Build reverse lookup: first name ΓåÆ emails, last name ΓåÆ emails    const jagritiNameIndex = {};    for (const [email, rec] of universe) {        const f = norm(rec.firstName), l = norm(rec.lastName);        if (f && f.length >= 3) (jagritiNameIndex[f] = jagritiNameIndex[f] || []).push({ email, rec });        if (l && l.length >= 3) (jagritiNameIndex[l] = jagritiNameIndex[l] || []).push({ email, rec });        const full = `${f} ${l}`.trim();        if (full && full !== ' ') jagritiNameIndex[full] = [{ email, rec }];    }    function matchJagriti(rawContrib) {        // Clean: strip parenthesized text, honorifics, dashes, ampersands        let cleaned = norm(rawContrib).replace(/\(.*?\)/g, '').replace(/\s*-\s*/g, ' ')            .replace(/\b(da|di|dada|didi|uncle|aunty|friend)\b/gi, '').replace(/\s+/g, ' ').trim();        // Split on & for multi-contributor        const contribs = cleaned.includes('&') ? cleaned.split('&').map(c => c.trim()) : [cleaned];        const matched = [];        for (const name of contribs) {            if (!name || name.length < 3) continue;            // Exact full name            if (jagritiNameIndex[name]) { matched.push(jagritiNameIndex[name][0]); continue; }            // Try first+last            const parts = name.split(/\s+/);            if (parts.length >= 2) {                const full = parts.join(' ');                if (jagritiNameIndex[full]) { matched.push(jagritiNameIndex[full][0]); continue; }            }            // Try first name only (unique)            const first = parts[0];            if (first && first.length >= 3 && jagritiNameIndex[first] && jagritiNameIndex[first].length === 1) {                matched.push(jagritiNameIndex[first][0]); continue;            }            // Try last name + first name prefix            if (parts.length >= 2) {                const last = parts[parts.length - 1];                if (last && jagritiNameIndex[last]) {                    const candidates = jagritiNameIndex[last].filter(c => norm(c.rec.firstName).startsWith(first.substring(0, 3)));                    if (candidates.length === 1) { matched.push(candidates[0]); continue; }                }            }        }        return matched;    }    let jagritiMatched = 0;    for (const j of sources.jagriti2022) {        if (!j.Contributor) continue;        const matches = matchJagriti(j.Contributor);        for (const { email, rec } of matches) {            rec.jagritiContributions.push({ year: '2022', type: j.Type || 'contributor', count: j.Count || 1, rawName: j.Contributor, source: 'jagriti_2022' });            rec.reconciliation.cultural.push({ year: '2022', type: j.Type, source: 'jagriti_2022' });            rec.importSources.add('jagriti');            jagritiMatched++;        }    }    for (const j of sources.jagriti2023) {        if (!j.Contributor) continue;        const matches = matchJagriti(j.Contributor);        for (const { email, rec } of matches) {            rec.jagritiContributions.push({ year: '2023', type: j.Type || 'contributor', count: j.Count || 1, comments: j.Comments || '', rawName: j.Contributor, source: 'jagriti_2023' });            rec.reconciliation.cultural.push({ year: '2023', type: j.Type, source: 'jagriti_2023' });            rec.importSources.add('jagriti');            jagritiMatched++;        }    }    console.log(`      ΓåÆ Jagriti matched: ${jagritiMatched}/${sources.jagriti2022.length + sources.jagriti2023.length} contributors`);    // ΓöÇΓöÇ SOURCE 9: Report Family Mapping ΓöÇΓöÇ    console.log('  [A] Reconciling names from Report Family Mapping...');    for (const fam of sources.reportFamilyMapping) {        for (const m of (fam.members || [])) {            if (!m.email) continue;            const rec = getOrCreate(m.email);            if (!rec) continue;            merge(rec, 'displayName', m.name, 'report_family_mapping');            if (!rec.firstName && m.name) {                merge(rec, 'firstName', m.name.split(' ')[0], 'report_family_mapping');                merge(rec, 'lastName', m.name.split(' ').slice(1).join(' '), 'report_family_mapping');            }            rec.importSources.add('report_family_mapping');        }    }    // ΓöÇΓöÇ SOURCE 10: Event Attendance (XLSX Evite Lists + Live Evite API + Volunteer POCs) ΓöÇΓöÇ    console.log('  [I] Reconciling Event Attendance...');    let eventMatched = 0, eventTotal = 0;    // 10a: Saraswati Puja XLSX EviteList (has email ΓÇö exact match)    if (sources.saraswatiPujaEvite) {        for (const row of sources.saraswatiPujaEvite) {            if (!row.Name || row.Name === 'undefined') continue;            eventTotal++;            const email = (row.Email || '').trim().toLowerCase();            let rec = null;            if (email && email.includes('@')) {                rec = universe.get(email);                if (!rec) rec = getOrCreate(email);            }            if (!rec) {                // Fuzzy name match                const cleaned = norm(row.Name);                const matchEmail = emailByFullMap[cleaned];                if (matchEmail) rec = universe.get(matchEmail);                if (!rec) {                    const first = cleaned.split(/\s+/)[0];                    if (first && emailByFirstMap[first] && emailByFirstMap[first].length === 1) {                        rec = universe.get(emailByFirstMap[first][0].email);                    }                }            }            if (rec) {                rec.eventAttendance.push({                    eventName: 'Saraswati Puja 2026', eventDate: '2026-02', rsvp: row.Status || 'Yes',                    adults: Math.max(1, (row.Count || 1) - 0), kids: 0, totalAttendees: row.Count || 1,                    dietary: 'unknown', amount: row.Amount || 0, isMember: row.Member || '', source: 'xlsx_evite'                });                rec.reconciliation.events.push({ event: 'Saraswati Puja 2026', rsvp: row.Status || 'Yes', source: 'xlsx_evite' });                rec.importSources.add('events');                eventMatched++;            }        }        console.log(`      ΓåÆ Saraswati Puja XLSX: matched ${eventMatched}/${eventTotal} evite entries`);    }    // 10b: Live Evite API RSVPs (name-based matching ΓÇö emails are all info@mailva.evite.com)    if (sources.eviteEvents) {        for (const evt of sources.eviteEvents) {            if (!evt.rsvps || evt.rsvps.length === 0) continue;            let evtMatched = 0;            for (const rsvp of evt.rsvps) {                if (!rsvp.senderName || rsvp.senderName === 'Evite') continue;                eventTotal++;                // Clean sender name: remove digits, clean                let sName = (rsvp.senderName || '').replace(/[0-9]+$/g, '').trim();                sName = sName.replace(/\s+/g, ' ');                const cleaned = norm(sName);                let rec = null;                // Try full name match                const matchEmail = emailByFullMap[cleaned];                if (matchEmail) rec = universe.get(matchEmail);                // Try first name only (unique)                if (!rec) {                    const first = cleaned.split(/\s+/)[0];                    if (first && first.length >= 3 && emailByFirstMap[first] && emailByFirstMap[first].length === 1) {                        rec = universe.get(emailByFirstMap[first][0].email);                    }                }                // Try prefix match on full name                if (!rec && cleaned.length >= 5) {                    for (const [full, em] of Object.entries(emailByFullMap)) {                        if (full.startsWith(cleaned.substring(0, 5)) || cleaned.startsWith(full.substring(0, 5))) {                            rec = universe.get(em);                            break;                        }                    }                }                if (rec) {                    rec.eventAttendance.push({                        eventName: evt.eventName, eventDate: evt.eventDate || '', rsvp: rsvp.rsvpStatus || 'unknown',                        adults: rsvp.adults || 0, kids: rsvp.kids || 0, totalAttendees: rsvp.totalAttendees || 0,                        dietary: rsvp.dietary || 'unknown', amount: 0, source: 'evite_api',                        llmConfidence: rsvp.llmConfidence || ''                    });                    rec.reconciliation.events.push({ event: evt.eventName, rsvp: rsvp.rsvpStatus, source: 'evite_api' });                    rec.importSources.add('events');                    evtMatched++;                }            }            console.log(`      ΓåÆ ${evt.eventName}: matched ${evtMatched}/${evt.rsvps.length} RSVPs`);        }    }    // 10c: Event XLSX Volunteer/POC names    if (sources.eventVolunteers) {        let volMatched = 0;        for (const vol of sources.eventVolunteers) {            if (!vol.name) continue;            const cleaned = norm(vol.name);            let rec = null;            const first = cleaned.split(/\s+/)[0];            // First try full name, then first name unique match            const matchEmail = emailByFullMap[cleaned];            if (matchEmail) rec = universe.get(matchEmail);            if (!rec && first && first.length >= 3 && emailByFirstMap[first] && emailByFirstMap[first].length === 1) {                rec = universe.get(emailByFirstMap[first][0].email);            }            if (rec) {                // Check if already have this volunteer role                const existing = rec.volunteerEvents.find(v => v.eventName === vol.eventName && v.role === vol.role);                if (!existing) {                    rec.volunteerEvents.push({ eventName: vol.eventName, role: vol.role, source: 'xlsx_volunteer' });                    rec.reconciliation.events.push({ event: vol.eventName, role: vol.role, source: 'xlsx_volunteer' });                    rec.importSources.add('events');                    volMatched++;                }            }        }        console.log(`      ΓåÆ Volunteer POCs: matched ${volMatched}/${sources.eventVolunteers.length}`);    }    console.log(`      ΓåÆ Total event records: ${eventMatched + (sources.eviteEvents ? sources.eviteEvents.reduce((s, e) => s + (e.rsvps || []).length, 0) : 0)} RSVPs + ${(sources.eventVolunteers || []).length} volunteer entries`);    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    // APPLY HOUSEHOLD UNITS (Membership Payment = Primary Signal)    // ~82 paid membership units in 2025-26    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    console.log('  [B1] Building household units (membership payment = primary signal)...');    const eventDataByEmail = {};    for (const [email, rec] of universe) {        if (rec.eventAttendance.length > 0) eventDataByEmail[email] = rec.eventAttendance;    }    // Name resolution function for membership XLSX matching    const resolveForHH = (firstName, lastName) => {        const f = norm(firstName), l = norm(lastName);        const full = `${f} ${l}`.trim();        if (emailByFullMap[full]) return emailByFullMap[full];        if (f && l && l.length >= 3) {            for (const [key, email] of Object.entries(emailByFullMap)) {                const kp = key.split(' ');                if (kp[0] === f && kp.slice(1).join(' ').startsWith(l.substring(0, 4))) return email;                if (kp[0] === f && l.startsWith(kp.slice(1).join(' ').substring(0, 4))) return email;            }        }        if (f && emailByFirstMap[f] && emailByFirstMap[f].length === 1) return emailByFirstMap[f][0].email;        // Wider match: first-name-only (after honorific stripping) ΓÇö allow up to 3 candidates        if (f && !l && emailByFirstMap[f] && emailByFirstMap[f].length <= 3) return emailByFirstMap[f][0].email;        // Prefix match on first name (at least 4 chars, unique prefix)        if (f && f.length >= 4 && !l) {            const prefix = f.substring(0, 4);            const candidates = [];            for (const [fn, entries] of Object.entries(emailByFirstMap)) {                if (fn.startsWith(prefix)) candidates.push(...entries);            }            if (candidates.length === 1) return candidates[0].email;        }        return null;    };    const households = familyGraph.buildHouseholds(eventDataByEmail, sources.membership2526, resolveForHH);    for (const [hhId, hh] of households) {        const memberEmails = [...hh.members];        for (let idx = 0; idx < memberEmails.length; idx++) {            const rec = universe.get(memberEmails[idx]);            if (!rec) continue;            rec.householdId = hhId;            rec.householdType = hh.type;            rec.householdDisplayName = hh.displayName;            rec.householdRole = idx === 0 ? 'primary' : 'spouse';            rec.inferredKids = hh.inferredKids;            rec.householdMembers = memberEmails.filter(e => e !== rec.email).map(e => {                const m = universe.get(e);                return m ? { email: e, firstName: m.firstName, lastName: m.lastName, displayName: m.displayName } : { email: e };            });            rec.householdEvidence = hh.spouseEvidence;            rec.householdMembershipCategory = hh.membershipCategory || '';            rec.householdMembershipAmount = hh.membershipAmount || 0;            rec.householdYearActive = hh.yearActive || [];        }    }    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    // APPLY FAMILY NETWORK (Relationships ΓÇö broader connections)    // Max group size capped at 6 to prevent runaway chains    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    console.log('  [B2] Building family networks (relationships, max 6 per group)...');    const families = familyGraph.buildFamilies(3, 6); // threshold=3, maxSize=6    for (const [fid, family] of families) {        for (const email of family.members) {            const rec = universe.get(email);            if (!rec) continue;            rec.familyId = fid;            rec.familyType = family.type;            rec.familyDisplayName = family.displayName;            rec.familyMembers = [...family.members].filter(e => e !== email).map(e => {                const m = universe.get(e);                return m ? { email: e, firstName: m.firstName, lastName: m.lastName, displayName: m.displayName } : { email: e };            });            rec.familyEvidence = family.evidence;            rec.reconciliation.family.push({                familyId: fid, type: family.type, displayName: family.displayName,                members: family.members.size, evidence: family.evidence.length,                totalWeight: family.totalWeight, source: 'intelligent_graph'            });        }    }    // ΓöÇΓöÇ Fix names and finalize ΓöÇΓöÇ    console.log('  Fixing names and finalizing...');    for (const [email, rec] of universe) {        if (rec.firstName === email || rec.firstName === '') {            if (rec.displayName && rec.displayName !== email) {                const parts = rec.displayName.split(' ');                rec.firstName = parts[0] || ''; rec.lastName = parts.slice(1).join(' ') || '';            }        }        rec.firstName = titleCase(rec.firstName);        rec.lastName = titleCase(rec.lastName);        if (!rec.displayName || rec.displayName === email) {            rec.displayName = [rec.firstName, rec.lastName].filter(Boolean).join(' ') || email;        }        rec.membershipYears = [...rec.membershipYears].sort();        rec.membershipTypes = [...rec.membershipTypes];        rec.importSources = [...rec.importSources];        // Detect issues        if (!rec.phone) rec.issues.push({ severity: 'warning', area: 'personal', msg: 'No phone number' });        if (!rec.firstName || rec.firstName === email) rec.issues.push({ severity: 'error', area: 'personal', msg: 'Missing proper name' });        if (!rec.familyId || rec.familyType === 'individual') {} // OK        if (rec.membershipYears.length === 0) rec.issues.push({ severity: 'info', area: 'membership', msg: 'No membership year recorded' });        if (rec.paymentRecords.length === 0) rec.issues.push({ severity: 'info', area: 'payment', msg: 'No payment records' });        if (rec.orgRoles.length === 0) rec.issues.push({ severity: 'info', area: 'orgRole', msg: 'No org roles' });        if (rec.communications === 0) rec.issues.push({ severity: 'info', area: 'communication', msg: 'No communications logged' });        if (rec.eventAttendance.length === 0 && rec.volunteerEvents.length === 0) rec.issues.push({ severity: 'info', area: 'events', msg: 'No event attendance recorded' });        // Reconciliation summary per dimension        const dims = rec.reconciliation;        const personalConflicts = dims.personal.filter(r => r.action === 'conflict');        if (personalConflicts.length > 0) {            rec.issues.push({ severity: 'warning', area: 'personal', msg: `${personalConflicts.length} field conflicts across sources` });        }    }    return universe;}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// PHASE 2B: RELATIONSHIP MANAGEMENT ENGINE//   Multi-agent system for inferring and managing family//   relationships with full audit trail// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// ΓöÇΓöÇ RELATIONSHIP TAXONOMY ΓöÇΓöÇconst REL_TYPES = {    husband:        { label: 'Husband',         inverse: 'wife',            category: 'spouse',  icon: '≡ƒÆì', color: '#ec4899' },    wife:           { label: 'Wife',            inverse: 'husband',         category: 'spouse',  icon: '≡ƒÆì', color: '#ec4899' },    father:         { label: 'Father',          inverse: 'child',           category: 'parent',  icon: '≡ƒæ¿', color: '#3b82f6' },    mother:         { label: 'Mother',          inverse: 'child',           category: 'parent',  icon: '≡ƒæ⌐', color: '#a855f7' },    son:            { label: 'Son',             inverse: 'parent',          category: 'child',   icon: '≡ƒæª', color: '#22c55e' },    daughter:       { label: 'Daughter',        inverse: 'parent',          category: 'child',   icon: '≡ƒæº', color: '#14b8a6' },    brother:        { label: 'Brother',         inverse: 'sibling',         category: 'sibling', icon: '≡ƒæ¼', color: '#eab308' },    sister:         { label: 'Sister',          inverse: 'sibling',         category: 'sibling', icon: '≡ƒæ¡', color: '#f97316' },    father_in_law:  { label: 'Father-in-Law',   inverse: 'child_in_law',   category: 'in_law',  icon: '≡ƒæ┤', color: '#06b6d4' },    mother_in_law:  { label: 'Mother-in-Law',   inverse: 'child_in_law',   category: 'in_law',  icon: '≡ƒæ╡', color: '#8b5cf6' },    son_in_law:     { label: 'Son-in-Law',       inverse: 'parent_in_law', category: 'in_law',  icon: '≡ƒñ╡', color: '#64748b' },    daughter_in_law:{ label: 'Daughter-in-Law',  inverse: 'parent_in_law', category: 'in_law',  icon: '≡ƒæ░', color: '#64748b' },    relative:       { label: 'Relative',        inverse: 'relative',        category: 'other',   icon: '≡ƒæÑ', color: '#94a3b8' }};const REL_CATEGORIES = {    spouse:  { label: 'Spouse',   icon: '≡ƒÆì', color: '#ec4899', priority: 1 },    parent:  { label: 'Parent',   icon: '≡ƒæ¿ΓÇì≡ƒæ⌐ΓÇì≡ƒæº', color: '#3b82f6', priority: 2 },    child:   { label: 'Child',    icon: '≡ƒæ╢', color: '#22c55e', priority: 3 },    sibling: { label: 'Sibling',  icon: '≡ƒæ½', color: '#eab308', priority: 4 },    in_law:  { label: 'In-Law',   icon: '≡ƒñ¥', color: '#06b6d4', priority: 5 },    other:   { label: 'Other',    icon: '≡ƒæÑ', color: '#94a3b8', priority: 6 }};function buildRelationships(universe, familyGraph, sources) {    console.log('\n[PHASE 2B] Building Relationship Graph...');    const relationships = [];  // Array of relationship records    let relIdCounter = 0;    const relIndex = new Map();  // email ΓåÆ [rel records]    function addRel(fromEmail, toEmail, type, confidence, evidenceList, agent) {        const fk = norm(fromEmail), tk = norm(toEmail);        if (!fk || !tk || fk === tk) return null;        // Prevent duplicates: same pair + same type        const dupeKey = [fk, tk].sort().join('|') + '|' + type;        for (const r of relationships) {            const rk = [r.fromEmail, r.toEmail].sort().join('|') + '|' + r.type;            if (rk === dupeKey) {                // Merge evidence                r.evidence.push(...evidenceList);                r.confidence = Math.min(1, Math.max(r.confidence, confidence));                r.auditTrail.push({ ts: new Date().toISOString(), action: 'evidence_added', by: agent, detail: `+${evidenceList.length} evidence from ${agent}` });                return r;            }        }        const relId = 'REL-' + String(++relIdCounter).padStart(4, '0');        const rel = {            id: relId,            fromEmail: fk,            toEmail: tk,            type: type,            inverseType: REL_TYPES[type] ? REL_TYPES[type].inverse : 'relative',            confidence: confidence,            status: 'active',            evidence: evidenceList,            createdAt: new Date().toISOString(),            createdBy: agent,            updatedAt: '',            updatedBy: '',            auditTrail: [{ ts: new Date().toISOString(), action: 'created', by: agent, detail: `Inferred ${type} (confidence: ${(confidence * 100).toFixed(0)}%) from ${evidenceList.map(e => e.source).join(', ')}` }]        };        relationships.push(rel);        if (!relIndex.has(fk)) relIndex.set(fk, []);        if (!relIndex.has(tk)) relIndex.set(tk, []);        relIndex.get(fk).push(rel);        relIndex.get(tk).push(rel);        return rel;    }    // ΓöÇΓöÇ Build member signature for disambiguation ΓöÇΓöÇ    console.log('  [SIG] Building member signatures for disambiguation...');    const signatures = new Map();    for (const [email, m] of universe) {        const sigParts = [];        if (m.phone) sigParts.push('≡ƒô▒' + m.phone.slice(-4));        if (m.address || m.city) sigParts.push('≡ƒôì' + (m.city || m.address || '').substring(0, 15));        const spouse = m.householdMembers.map(h => h.displayName || h.email.split('@')[0]).join('/');        if (spouse) sigParts.push('≡ƒÆì' + spouse);        if (m.profession) sigParts.push('≡ƒÆ╝' + m.profession.substring(0, 12));        const emailDomain = email.split('@')[1];        if (emailDomain && emailDomain !== 'gmail.com' && emailDomain !== 'yahoo.com' && emailDomain !== 'hotmail.com') sigParts.push('≡ƒôº' + emailDomain);        if (m.education) sigParts.push('≡ƒÄô' + m.education.substring(0, 12));        // Membership years as fingerprint        if (m.membershipYears.length > 0) sigParts.push('≡ƒôï' + m.membershipYears.join(','));        signatures.set(email, {            email: email,            displayName: m.displayName || (m.firstName + ' ' + m.lastName).trim(),            signature: sigParts.join(' | '),            signatureShort: sigParts.slice(0, 3).join(' | '),            isAmbiguous: false  // set below for duplicate names        });    }    // Mark name duplicates    const nameMap = new Map();    for (const [email, sig] of signatures) {        const nk = norm(sig.displayName);        if (!nameMap.has(nk)) nameMap.set(nk, []);        nameMap.get(nk).push(email);    }    let ambiguousCount = 0;    for (const [name, emails] of nameMap) {        if (emails.length > 1) {            for (const e of emails) { signatures.get(e).isAmbiguous = true; ambiguousCount++; }        }    }    console.log(`      ΓåÆ ${signatures.size} signatures, ${ambiguousCount} ambiguous names`);    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    // AGENT 1: SPOUSE DETECTION (High Confidence)    // Sources: household pairs, Da/Di honorifics, +/& notation    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    console.log('  [AGENT-1] Spouse Detection...');    let spouseCount = 0;    // 1a: Household pairs (type couple/family with 2 members)    for (const [hhId, hh] of familyGraph.households) {        if (hh.members.size === 2 && (hh.type === 'couple' || hh.type === 'family')) {            const emails = [...hh.members];            const m0 = universe.get(norm(emails[0]));            const m1 = universe.get(norm(emails[1]));            if (m0 && m1) {                const g0 = (m0.gender || '').toLowerCase();                const g1 = (m1.gender || '').toLowerCase();                let type0, type1;                if (g0 === 'male' && g1 === 'female') { type0 = 'husband'; type1 = 'wife'; }                else if (g0 === 'female' && g1 === 'male') { type0 = 'wife'; type1 = 'husband'; }                else { type0 = 'husband'; type1 = 'wife'; } // default ΓÇö admin can fix                addRel(m0.email, m1.email, type0, 0.90,                    [{ source: 'household_pair', detail: `Household ${hhId} (${hh.type}): ${hh.displayName}`, weight: 10 }],                    'agent_spouse');                spouseCount++;            }        }    }    // 1b: XLSX Da/Di honorific patterns  (already pairs in membership data)    if (sources.membership2526) {        for (const row of sources.membership2526) {            const rawName = (row.Name || '').trim();            const dadiMatch = rawName.match(/^(.+?)\s+(Da|Dada)\s*[\\/&]\s*(.+?)\s+(Di|Didi)\s*$/i)                           || rawName.match(/^(.+?)\s+(Di|Didi)\s*[\\/&]\s*(.+?)\s+(Da|Dada)\s*$/i);            if (dadiMatch) {                // Try to match these names to universe members                const name1 = stripHonorifics(dadiMatch[1] + ' ' + (row['Last Name'] || rawName.split(/\s+/).pop())).trim();                const name2 = stripHonorifics(dadiMatch[3] + ' ' + (row['Last Name'] || rawName.split(/\s+/).pop())).trim();                // Find members by fuzzy name match within same household                for (const [hhId, hh] of familyGraph.households) {                    if (hh.members.size === 2) {                        const emails = [...hh.members];                        const m0 = universe.get(norm(emails[0]));                        const m1 = universe.get(norm(emails[1]));                        if (m0 && m1) {                            // Check if this Da/Di pair matches this household                            const n0 = norm(m0.displayName), n1 = norm(m1.displayName);                            if ((n0.includes(norm(dadiMatch[1])) || n1.includes(norm(dadiMatch[1]))) &&                                (n0.includes(norm(dadiMatch[3])) || n1.includes(norm(dadiMatch[3])))) {                                addRel(m0.email, m1.email, 'husband', 0.85,                                    [{ source: 'honorific_dadi', detail: `XLSX: "${rawName}" ΓÇö Da/Di = married couple`, weight: 8 }],                                    'agent_spouse_honorific');                            }                        }                    }                }            }        }    }    // 1c: "+" and "/" notation in raw entries    if (sources.rawEntries) {        for (const row of sources.rawEntries) {            const raw = (row.RawEntry || row['Raw Entry'] || row.Name || '').trim();            const plusMatch = raw.match(/^(.+?)\+(.+)$/);            const slashMatch = raw.match(/^(.+?)\s*\/\s*(.+)$/);            if (plusMatch || slashMatch) {                const match = plusMatch || slashMatch;                // These are couples ΓÇö add as evidence to existing spouse rels                // Try to find both in universe                for (const [hhId, hh] of familyGraph.households) {                    if (hh.members.size >= 2) {                        const emails = [...hh.members];                        for (let i = 0; i < emails.length - 1; i++) {                            for (let j = i + 1; j < emails.length; j++) {                                const mi = universe.get(norm(emails[i]));                                const mj = universe.get(norm(emails[j]));                                if (mi && mj) {                                    const ni = norm(mi.firstName || mi.displayName);                                    const nj = norm(mj.firstName || mj.displayName);                                    if ((ni.includes(norm(match[1])) && nj.includes(norm(match[2]))) ||                                        (ni.includes(norm(match[2])) && nj.includes(norm(match[1])))) {                                        addRel(mi.email, mj.email, 'husband', 0.80,                                            [{ source: 'raw_entry_pair', detail: `Raw: "${raw}" ΓÇö co-occurrence pair`, weight: 6 }],                                            'agent_spouse_notation');                                    }                                }                            }                        }                    }                }            }        }    }    console.log(`      ΓåÆ ${spouseCount} spouse pairs detected`);    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    // AGENT 2: PARENT-CHILD INFERENCE (Medium Confidence)    // Sources: EB-Family membership, event kids, family groups >2    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    console.log('  [AGENT-2] Parent-Child Inference...');    let parentChildCount = 0;    // 2a: Family Universe groups with >2 members (same familyId)    for (const [famId, fam] of familyGraph.families) {        if (fam.members.size > 2) {            // Get all member records            const famMembers = [...fam.members]                .map(email => universe.get(norm(email)))                .filter(Boolean);            if (famMembers.length <= 2) continue;            // Find the spouse pair (if any) in this family            const spouseEmails = new Set();            for (const rel of relationships) {                if (rel.type === 'husband' || rel.type === 'wife') {                    if (fam.members.has(rel.fromEmail) && fam.members.has(rel.toEmail)) {                        spouseEmails.add(rel.fromEmail);                        spouseEmails.add(rel.toEmail);                    }                }            }            // Members not in spouse pair are potential children or siblings            const parents = famMembers.filter(m => spouseEmails.has(m.email));            const others = famMembers.filter(m => !spouseEmails.has(m.email));            if (parents.length === 2 && others.length > 0) {                // We have a identified couple + other family members ΓåÆ likely parent-child                for (const child of others) {                    const childType = (child.gender || '').toLowerCase() === 'female' ? 'daughter' : 'son';                    for (const parent of parents) {                        const parentType = (parent.gender || '').toLowerCase() === 'female' ? 'mother' : 'father';                        addRel(parent.email, child.email, parentType, 0.55,                            [{ source: 'family_group_inference', detail: `Family ${famId}: ${fam.displayName} ΓÇö ${parents.length} parents + ${others.length} other members`, weight: 4 }],                            'agent_parent_child');                        parentChildCount++;                    }                }            }        }    }    // 2b: EB-Family households with event kid count > 0    for (const [hhId, hh] of familyGraph.households) {        if (hh.inferredKids > 0) {            // We know this household has children but don't have their emails            // Mark on the household members            for (const memberEmail of hh.members) {                const m = universe.get(norm(memberEmail));                if (m) {                    // Add a note ΓÇö kids exist but are not in CRM                    const existingForHH = relationships.filter(r =>                        (r.fromEmail === m.email || r.toEmail === m.email) &&                        (r.type === 'father' || r.type === 'mother'));                    if (existingForHH.length === 0 && hh.inferredKids > 0) {                        // No specific child identified ΓÇö add as "has_children" evidence                        addRel(m.email, m.email, 'relative', 0.50,                            [{ source: 'event_kids_count', detail: `${hh.inferredKids} kids from event RSVP ΓÇö children not in CRM`, weight: 2 }],                            'agent_parent_child_event');                    }                }            }        }    }    console.log(`      ΓåÆ ${parentChildCount} parent-child relationships inferred`);    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    // AGENT 3: SIBLING DETECTION (Low Confidence)    // Sources: Same family group, not in spouse pair, same surname    // ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ    console.log('  [AGENT-3] Sibling Detection...');    let siblingCount = 0;    for (const [famId, fam] of familyGraph.families) {        if (fam.members.size > 2) {            const famMembers = [...fam.members].map(email => universe.get(norm(email))).filter(Boolean);            const spouseEmails = new Set();            for (const rel of relationships) {                if (rel.type === 'husband' || rel.type === 'wife') {                    if (fam.members.has(rel.fromEmail) && fam.members.has(rel.toEmail)) {                        spouseEmails.add(rel.fromEmail);                        spouseEmails.add(rel.toEmail);                    }                }            }            const nonSpouse = famMembers.filter(m => !spouseEmails.has(m.email));            // Look for sibling pairs (same surname, not already linked)            for (let i = 0; i < nonSpouse.length - 1; i++) {                for (let j = i + 1; j < nonSpouse.length; j++) {                    const a = nonSpouse[i], b = nonSpouse[j];                    if (norm(a.lastName) === norm(b.lastName) && a.lastName) {                        const sibType = 'brother'; // default; admin can fix to sister                        addRel(a.email, b.email, sibType, 0.40,                            [{ source: 'sibling_inference', detail: `Same surname "${a.lastName}" in family ${famId}, not in spouse pair`, weight: 3 }],                            'agent_sibling');                        siblingCount++;                    }                }            }        }    }    console.log(`      ΓåÆ ${siblingCount} sibling relationships inferred`);    // ΓöÇΓöÇ Remove self-referential placeholder rels ΓöÇΓöÇ    const finalRels = relationships.filter(r => r.fromEmail !== r.toEmail);    // ΓöÇΓöÇ Summary ΓöÇΓöÇ    const relByType = {};    for (const r of finalRels) { relByType[r.type] = (relByType[r.type] || 0) + 1; }    console.log(`  [DONE] ${finalRels.length} relationships total:`);    for (const [t, c] of Object.entries(relByType).sort((a, b) => b[1] - a[1])) {        console.log(`         ${t}: ${c}`);    }    return { relationships: finalRels, signatures, relIndex, relByType };}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// PHASE 3: HTML REPORT GENERATOR// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉfunction generateReport(universe, familyGraph, sources, relData) {    const members = [...universe.values()].sort((a, b) => a.displayName.localeCompare(b.displayName));    const families = familyGraph.families;    const households = familyGraph.households;    // Stats    const total = members.length;    const withPhone = members.filter(m => m.phone).length;    const withFamily = members.filter(m => m.familyMembers.length > 0).length;    const withPayment = members.filter(m => m.paymentRecords.length > 0).length;    const withOrgRole = members.filter(m => m.orgRoles.length > 0).length;    const withComms = members.filter(m => m.communications > 0).length;    const withJagriti = members.filter(m => m.jagritiContributions.length > 0).length;    const withEvents = members.filter(m => m.eventAttendance.length > 0 || m.volunteerEvents.length > 0).length;    const ecMembers = members.filter(m => m.isECMember).length;    const multiYear = members.filter(m => m.membershipYears.length > 1).length;    const noName = members.filter(m => !m.firstName || m.firstName === m.email).length;    // Family Network stats    const totalFamilies = families.size;    const coupleFams = [...families.values()].filter(f => f.type === 'couple').length;    const familyFams = [...families.values()].filter(f => f.type === 'family').length;    const individualFams = [...families.values()].filter(f => f.type === 'individual').length;    // Household stats    const totalHouseholds = households.size;    const coupleHouseholds = [...households.values()].filter(h => h.type === 'couple').length;    const familyHouseholds = [...households.values()].filter(h => h.type === 'family').length;    const individualHouseholds = [...households.values()].filter(h => h.type === 'individual').length;    const householdsWithKids = [...households.values()].filter(h => h.inferredKids > 0).length;    const totalInferredKids = [...households.values()].reduce((s, h) => s + h.inferredKids, 0);    const sourceCount = {};    for (const m of members) for (const s of m.importSources) sourceCount[s] = (sourceCount[s] || 0) + 1;    // Reconciliation dimension completeness    const dimStats = {        personal: { complete: members.filter(m => m.firstName && m.lastName && m.email).length, partial: members.filter(m => m.firstName || m.email).length },        family: { complete: members.filter(m => m.familyMembers.length > 0).length, partial: members.filter(m => m.familyId).length },        membership: { complete: members.filter(m => m.membershipYears.length > 0).length, partial: members.length },        payment: { complete: withPayment, partial: members.length },        orgRole: { complete: withOrgRole, partial: members.length },        volunteer: { complete: members.filter(m => m.volunteerRecords.length > 0).length, partial: members.length },        cultural: { complete: withJagriti, partial: members.length },        communication: { complete: withComms, partial: members.length },        events: { complete: withEvents, partial: members.length }    };    const unmatchedNames = sources._unmatchedMembership || [];    // ΓöÇΓöÇ FAMILY EVIDENCE SUMMARY ΓöÇΓöÇ    const edgeTypeCounts = {};    for (const [key, edge] of familyGraph.edges) {        for (const ev of edge.evidence) {            edgeTypeCounts[ev.type] = (edgeTypeCounts[ev.type] || 0) + 1;        }    }    // ΓöÇΓöÇ Prepare client-side lineage + edit data ΓöÇΓöÇ    const ecRoster = [];    if (sources.adminReport && sources.adminReport.report) {        for (const term of (sources.adminReport.report.ecTerms || [])) {            for (const c of (term.contacts || [])) {                if (c.email) ecRoster.push({ email: norm(c.email), title: (c.roles || []).join(', '), name: c.name || '' });            }        }    }    const memberLineage = members.map((m, i) => ({        e: m.email, n: m.displayName,        rp: m.reconciliation.personal,        rf: m.reconciliation.family,        rm: m.reconciliation.membership,        rpay: m.reconciliation.payment,        ro: m.reconciliation.orgRole,        rc: m.reconciliation.cultural,        rco: m.reconciliation.communication,        rev: m.reconciliation.events,        pr: m.paymentRecords.map(p => ({ y: p.year, c: p.category, a: p.amount, s: p.source, r: p.rawName })),        tp: m.totalPaid,        ea: m.eventAttendance.map(e => ({ en: e.eventName, rv: e.rsvp, s: e.source, ad: e.adults, ki: e.kids, am: e.amount, d: e.dietary })),        ve: m.volunteerEvents.map(v => ({ en: v.eventName, ro: v.role, s: v.source })),        jc: m.jagritiContributions.map(j => ({ y: j.year, t: j.type, c: j.count, s: j.source, cm: j.comments })),        or: m.orgRoles.map(r => ({ t: r.term, ro: r.role, s: r.source })),        cm: m.communications,        src: m.importSources,        iss: m.issues,        // Household info        hh: { id: m.householdId, type: m.householdType, name: m.householdDisplayName, role: m.householdRole, kids: m.inferredKids,              spouse: m.householdMembers.map(f => f.displayName || f.email).join(', '),              evidence: m.householdEvidence.map(e => ({ type: e.type, detail: e.detail })),              cat: m.householdMembershipCategory, amt: m.householdMembershipAmount,              years: m.householdYearActive, updated: new Date().toISOString() },        // Signature for disambiguation        sig: relData.signatures.get(m.email) ? relData.signatures.get(m.email).signature : '',        sigShort: relData.signatures.get(m.email) ? relData.signatures.get(m.email).signatureShort : '',        isAmb: relData.signatures.get(m.email) ? relData.signatures.get(m.email).isAmbiguous : false    }));    const lineageJSON = JSON.stringify(memberLineage).replace(/<\//g, '<\\/');    const ecRosterJSON = JSON.stringify(ecRoster).replace(/<\//g, '<\\/');    // ΓöÇΓöÇ Prepare relationship data for client-side ΓöÇΓöÇ    const relJSON = JSON.stringify(relData.relationships.map(r => ({        id: r.id, f: r.fromEmail, t: r.toEmail, tp: r.type, inv: r.inverseType,        conf: r.confidence, st: r.status, ev: r.evidence,        cat: r.createdAt, cab: r.createdBy, uat: r.updatedAt, uab: r.updatedBy,        aud: r.auditTrail    }))).replace(/<\//g, '<\\/');    const relTypesJSON = JSON.stringify(REL_TYPES).replace(/<\//g, '<\\/');    // Relationship stats    const totalRels = relData.relationships.filter(r => r.fromEmail !== r.toEmail).length;    const spouseRels = relData.relationships.filter(r => r.type === 'husband' || r.type === 'wife').length;    const parentChildRels = relData.relationships.filter(r => r.type === 'father' || r.type === 'mother').length;    const siblingRels = relData.relationships.filter(r => r.type === 'brother' || r.type === 'sister').length;    const membersWithRels = new Set();    for (const r of relData.relationships) { if (r.fromEmail !== r.toEmail) { membersWithRels.add(r.fromEmail); membersWithRels.add(r.toEmail); } }    const html = `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>BANF CRM Complete Reconciliation Report</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" rel="stylesheet"><style>:root{--bg:#060a10;--bg2:#0b1120;--card:#0f172a;--panel:#111827;--line:#1e293b;--text:#e2e8f0;--muted:#94a3b8;--dim:#475569;--accent:#f97316;--green:#22c55e;--red:#ef4444;--blue:#3b82f6;--purple:#a855f7;--cyan:#06b6d4;--yellow:#eab308;--pink:#ec4899;--teal:#14b8a6}*{box-sizing:border-box;margin:0}body{background:var(--bg);color:var(--text);font-family:'Segoe UI',system-ui,sans-serif}.hdr{background:linear-gradient(135deg,#1a1033,#0f172a);border-bottom:1px solid var(--line);padding:20px 28px;display:flex;justify-content:space-between;align-items:center}.hdr h1{font-size:1.3rem;color:var(--accent);margin:0}.hdr small{color:var(--muted);font-size:.72rem}.wrap{padding:16px 28px}.stat{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px;text-align:center}.stat .n{font-size:1.8rem;font-weight:800;color:var(--accent)}.stat .l{font-size:.7rem;color:var(--muted);margin-top:2px}.tabs{display:flex;gap:3px;margin-bottom:0;flex-wrap:wrap}.tab{background:var(--bg2);border:1px solid var(--line);color:var(--muted);padding:7px 14px;border-radius:8px 8px 0 0;cursor:pointer;font-size:.78rem;font-weight:600;white-space:nowrap}.tab.on{background:var(--card);color:var(--accent);border-bottom-color:var(--card)}.tpanel{display:none;background:var(--card);border:1px solid var(--line);border-top:none;border-radius:0 0 10px 10px;padding:18px}.tpanel.on{display:block}.sbox{background:var(--bg2);border:1px solid var(--line);color:var(--text);padding:9px 14px;border-radius:7px;width:100%;font-size:.85rem;margin-bottom:12px}.sbox:focus{outline:none;border-color:var(--accent)}table{width:100%;border-collapse:collapse;font-size:.78rem}th{background:var(--bg2);color:var(--muted);padding:8px 10px;text-align:left;border-bottom:2px solid var(--line);position:sticky;top:0;z-index:1}td{padding:6px 10px;border-bottom:1px solid var(--line)}tr:hover td{background:rgba(249,115,22,.03)}.badge{display:inline-block;padding:1px 7px;border-radius:4px;font-size:.6rem;font-weight:700;margin:1px}.b-crm{background:rgba(59,130,246,.15);color:#60a5fa}.b-google{background:rgba(34,197,94,.15);color:#4ade80}.b-family{background:rgba(168,85,247,.15);color:#c084fc}.b-member{background:rgba(249,115,22,.15);color:#fb923c}.b-audit{background:rgba(6,182,212,.15);color:#22d3ee}.b-jagriti{background:rgba(236,72,153,.15);color:#f472b6}.b-admin{background:rgba(234,179,8,.15);color:#facc15}.b-other{background:rgba(148,163,184,.15);color:#94a3b8}.b-event{background:rgba(244,63,94,.15);color:#fb7185}/* ΓöÇΓöÇ Lineage & Edit System ΓöÇΓöÇ */.fv-icon{cursor:pointer;opacity:.45;font-size:.58rem;margin-left:4px;transition:opacity .2s;vertical-align:middle}.fv-icon:hover{opacity:1}.fv-lineage{color:var(--cyan)}.fv-edit{color:var(--accent)}.fv-restricted{color:var(--yellow)}.modal-overlay{display:none;position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.7);z-index:9999;justify-content:center;align-items:center;backdrop-filter:blur(3px)}.modal-box{background:var(--card);border:1px solid var(--line);border-radius:12px;width:95%;max-width:720px;max-height:85vh;overflow-y:auto;box-shadow:0 20px 60px rgba(0,0,0,.6)}.modal-hdr{display:flex;justify-content:space-between;align-items:center;padding:16px 20px;border-bottom:1px solid var(--line)}.modal-hdr h5{color:var(--accent);font-size:.9rem;margin:0}.modal-close{background:none;border:none;color:var(--muted);font-size:1.4rem;cursor:pointer;line-height:1}.modal-close:hover{color:var(--red)}.modal-body{padding:20px}.lin-tree{border-left:2px solid var(--line);padding-left:16px;margin:8px 0}.lin-step{display:flex;gap:10px;padding:8px 0;border-bottom:1px dashed rgba(30,41,59,.5);position:relative}.lin-step:before{content:'';position:absolute;left:-20px;top:14px;width:12px;height:2px;background:var(--line)}.lin-icon{font-size:.9rem;min-width:20px;text-align:center}.lin-detail{flex:1;font-size:.75rem}.lin-action{font-weight:700;text-transform:uppercase;font-size:.6rem;letter-spacing:.5px;margin-bottom:2px}.lin-set .lin-action{color:var(--green)}.lin-conflict .lin-action{color:var(--yellow)}.lin-val{color:var(--text)}.lin-old{color:var(--red);font-size:.7rem}.lin-src{color:var(--muted);font-size:.68rem;margin-top:2px}.lin-empty{color:var(--dim);font-size:.75rem;padding:10px;background:var(--bg2);border-radius:6px}.lin-calc{background:var(--bg2);border-radius:6px;padding:12px;margin:8px 0}.lin-calc-row{display:flex;justify-content:space-between;font-size:.75rem;padding:3px 0;border-bottom:1px dashed rgba(30,41,59,.3)}.lin-calc-total{font-weight:700;color:var(--accent);border-top:2px solid var(--accent);padding-top:4px;margin-top:4px}.lin-section{margin-bottom:16px}.lin-section h6{color:var(--cyan);font-size:.72rem;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px}.edit-form{background:var(--bg2);border-radius:8px;padding:16px;margin-top:8px}.edit-form label{display:block;font-size:.72rem;color:var(--muted);margin-bottom:3px}.edit-form input,.edit-form select,.edit-form textarea{background:var(--bg);border:1px solid var(--line);color:var(--text);padding:7px 10px;border-radius:5px;width:100%;font-size:.8rem;margin-bottom:8px}.edit-form input:focus,.edit-form textarea:focus{border-color:var(--accent);outline:none}.btn-save{background:var(--accent);color:#fff;border:none;padding:7px 18px;border-radius:5px;font-size:.75rem;font-weight:700;cursor:pointer}.btn-save:hover{background:#ea580c}.btn-cancel{background:transparent;border:1px solid var(--line);color:var(--muted);padding:7px 18px;border-radius:5px;font-size:.75rem;cursor:pointer;margin-left:6px}.btn-request{background:var(--yellow);color:#000;border:none;padding:7px 18px;border-radius:5px;font-size:.75rem;font-weight:700;cursor:pointer}.auth-bar{display:flex;align-items:center;gap:8px}.auth-bar .abtn{background:var(--accent);color:#fff;border:none;padding:4px 12px;border-radius:5px;cursor:pointer;font-size:.72rem;font-weight:600}.auth-bar .abtn:hover{background:#ea580c}.auth-bar .arole{color:var(--green);font-size:.65rem}.auth-bar .aname{color:var(--text);font-size:.72rem}.approval-banner{background:rgba(234,179,8,.1);border:1px solid rgba(234,179,8,.3);border-radius:6px;padding:10px 14px;margin-bottom:10px;font-size:.75rem}.approval-banner .ab-title{color:var(--yellow);font-weight:700}.tier-badge{display:inline-block;padding:1px 6px;border-radius:3px;font-size:.55rem;font-weight:700;margin-left:4px}.tier-basic{background:rgba(34,197,94,.12);color:var(--green)}.tier-restricted{background:rgba(234,179,8,.12);color:var(--yellow)}.b-year{background:rgba(59,130,246,.1);color:var(--blue);padding:1px 5px;border-radius:3px;font-size:.58rem}.b-ec{background:rgba(249,115,22,.15);color:var(--accent)}.b-active{background:rgba(34,197,94,.12);color:var(--green)}.b-fam{background:rgba(168,85,247,.1);color:var(--purple);padding:1px 5px;border-radius:3px;font-size:.58rem}.dim-bar{height:8px;border-radius:4px;background:var(--line);overflow:hidden;margin-top:4px}.dim-fill{height:100%;border-radius:4px}.detail{display:none;background:var(--bg2);border:1px solid var(--line);border-radius:8px;padding:16px;margin:6px 0}.detail.on{display:block}.dg{display:grid;grid-template-columns:130px 1fr;gap:3px 10px;font-size:.76rem}.dg .k{color:var(--dim);font-weight:600}.dg .v{color:var(--text)}.dsec{margin-bottom:12px}.dsec h6{color:var(--accent);font-size:.72rem;margin-bottom:5px;text-transform:uppercase;letter-spacing:.5px}.ev-tag{display:inline-block;padding:2px 6px;border-radius:3px;font-size:.58rem;font-weight:600;margin:1px}.ev-family_fix_mapping{background:rgba(34,197,94,.15);color:#4ade80}.ev-family_universe_v3{background:rgba(59,130,246,.15);color:#60a5fa}.ev-raw_entry_cooccurrence{background:rgba(168,85,247,.15);color:#c084fc}.ev-membership_xlsx_couple{background:rgba(249,115,22,.15);color:#fb923c}.ev-report_family_mapping{background:rgba(6,182,212,.15);color:#22d3ee}.ev-crm_existing_family{background:rgba(148,163,184,.15);color:#94a3b8}.ev-surname_domain{background:rgba(234,179,8,.15);color:#facc15}.ev-cross_year_frequency{background:rgba(236,72,153,.15);color:#f472b6}.issue-w{color:var(--yellow);font-size:.7rem}.issue-e{color:var(--red);font-size:.7rem}.issue-i{color:var(--blue);font-size:.7rem}.conflict{background:rgba(239,68,68,.08);border:1px solid rgba(239,68,68,.2);border-radius:4px;padding:4px 8px;font-size:.7rem;margin:2px 0}.recon-row{display:flex;gap:6px;font-size:.7rem;align-items:center;padding:2px 0}.recon-label{color:var(--dim);min-width:60px}.recon-val{color:var(--text)}.recon-src{color:var(--muted);font-style:italic}#mCount{color:var(--accent);font-weight:700}.fam-card{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:14px;margin-bottom:10px}.fam-card h6{color:var(--accent);margin:0 0 6px;font-size:.85rem}.ev-membership_xlsx_payment{background:rgba(249,115,22,.15);color:#fb923c}.hh-admin-card{background:var(--bg2);border:1px solid var(--line);border-radius:8px;padding:10px;margin-bottom:6px;cursor:pointer;transition:border-color .2s}.hh-admin-card:hover{border-color:var(--accent)}.hh-admin-card.selected{border-color:var(--green);box-shadow:0 0 8px rgba(34,197,94,.2)}.hh-member-chip{display:inline-flex;align-items:center;gap:4px;background:var(--card);border:1px solid var(--line);border-radius:16px;padding:3px 10px;font-size:.72rem;margin:2px}.hh-member-chip .remove{color:var(--red);cursor:pointer;font-size:.6rem;opacity:.5}.hh-member-chip .remove:hover{opacity:1}.hh-btn{padding:4px 10px;border-radius:5px;font-size:.68rem;font-weight:600;cursor:pointer;border:1px solid var(--line);background:var(--bg);color:var(--text);transition:all .2s}.hh-btn:hover{border-color:var(--accent);color:var(--accent)}.hh-btn-primary{background:var(--accent);color:#fff;border-color:var(--accent)}.hh-btn-primary:hover{background:#ea580c}.hh-btn-danger{border-color:var(--red);color:var(--red)}.hh-btn-danger:hover{background:rgba(239,68,68,.1)}.hh-change-log{max-height:200px;overflow-y:auto;font-size:.68rem;background:var(--bg);border:1px solid var(--line);border-radius:6px;padding:8px}.hh-change-log .entry{padding:3px 0;border-bottom:1px dashed rgba(30,41,59,.3)}</style></head><body><div class="hdr">  <div><h1><i class="fas fa-database me-2"></i>BANF CRM Complete Reconciliation</h1>  <small>Generated: ${new Date().toLocaleString()} | ${total} members | ${coupleHouseholds + familyHouseholds} households (${coupleHouseholds} couples, ${familyHouseholds} families) | ${totalFamilies} family networks</small></div>  <div style="text-align:right"><small style="color:var(--green)"><i class="fas fa-shield-halved me-1"></i>9-Dimension Reconciliation</small><br>  <small style="color:var(--purple)"><i class="fas fa-project-diagram me-1"></i>${familyGraph.edges.size} edges | max 6/network</small>  <div class="auth-bar" id="authBar" style="margin-top:6px"><button class="abtn" onclick="showAuthModal()"><i class="fas fa-lock me-1"></i>Admin Login</button></div>  </div></div><div class="wrap"><div class="tabs">  <div class="tab on" onclick="showTab('overview')"><i class="fas fa-chart-pie me-1"></i>Overview</div>  <div class="tab" onclick="showTab('members')"><i class="fas fa-users me-1"></i>Members</div>  <div class="tab" onclick="showTab('families')"><i class="fas fa-people-roof me-1"></i>Families</div>  <div class="tab" onclick="showTab('recon')"><i class="fas fa-arrows-rotate me-1"></i>Reconciliation</div>  <div class="tab" onclick="showTab('gaps')"><i class="fas fa-triangle-exclamation me-1"></i>Data Gaps</div>  <div class="tab" onclick="showTab('evidence')"><i class="fas fa-link me-1"></i>Family Evidence</div>  <div class="tab" onclick="showTab('events')"><i class="fas fa-calendar-check me-1"></i>Events</div>  <div class="tab" onclick="showTab('relationships')"><i class="fas fa-heart me-1"></i>Relationships</div>  <div class="tab" onclick="showTab('plan')"><i class="fas fa-clipboard-list me-1"></i>Plan</div>  <div class="tab" onclick="showTab('sources')"><i class="fas fa-layer-group me-1"></i>Sources</div></div><!-- ΓòÉΓòÉΓòÉ OVERVIEW ΓòÉΓòÉΓòÉ --><div class="tpanel on" id="tp-overview">  <div class="row g-3 mb-4">    <div class="col-6 col-md-2"><div class="stat"><div class="n">${total}</div><div class="l">Universe</div></div></div>    <div class="col-6 col-md-2"><div class="stat"><div class="n">${coupleHouseholds + familyHouseholds}</div><div class="l">Households</div></div></div>    <div class="col-6 col-md-2"><div class="stat"><div class="n">${withPhone}</div><div class="l">With Phone</div></div></div>    <div class="col-6 col-md-2"><div class="stat"><div class="n">${withPayment}</div><div class="l">Payments</div></div></div>    <div class="col-6 col-md-2"><div class="stat"><div class="n">${ecMembers}</div><div class="l">EC Members</div></div></div>    <div class="col-6 col-md-2"><div class="stat"><div class="n">${withEvents}</div><div class="l">Event Records</div></div></div>  </div>  <div class="row g-3">    <div class="col-md-6">      <div style="background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px">        <h6 style="color:var(--accent);font-size:.82rem"><i class="fas fa-cube me-1"></i>8 Reconciliation Dimensions</h6>        ${Object.entries(dimStats).map(([dim, s]) => {            const pct = total > 0 ? (s.complete / total * 100).toFixed(0) : 0;            const colors = { personal: '#3b82f6', family: '#a855f7', membership: '#22c55e', payment: '#f97316', orgRole: '#eab308', volunteer: '#06b6d4', cultural: '#ec4899', communication: '#14b8a6', events: '#f43f5e' };            const icons = { personal: 'user', family: 'people-roof', membership: 'id-card', payment: 'credit-card', orgRole: 'id-badge', volunteer: 'hand-holding-heart', cultural: 'music', communication: 'envelope', events: 'calendar-check' };            return `<div style="margin-bottom:8px"><div style="display:flex;justify-content:space-between;font-size:.75rem">              <span><i class="fas fa-${icons[dim]} me-1" style="color:${colors[dim]}"></i>${dim.charAt(0).toUpperCase() + dim.slice(1)}</span>              <span style="color:${colors[dim]}">${s.complete}/${total} (${pct}%)</span>            </div><div class="dim-bar"><div class="dim-fill" style="width:${pct}%;background:${colors[dim]}"></div></div></div>`;        }).join('\n')}      </div>    </div>    <div class="col-md-6">      <div style="background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px">        <h6 style="color:var(--accent);font-size:.82rem"><i class="fas fa-project-diagram me-1"></i>Family Grouping Evidence</h6>        <table><thead><tr><th>Evidence Type</th><th>Edges</th><th>Weight</th></tr></thead><tbody>          ${Object.entries(edgeTypeCounts).sort((a, b) => b[1] - a[1]).map(([t, c]) =>            `<tr><td><span class="ev-tag ev-${t}">${t.replace(/_/g, ' ')}</span></td><td>${c}</td><td>${{ family_fix_mapping: 12, family_universe_v3: 10, report_family_mapping: 10, raw_entry_cooccurrence: 8, membership_xlsx_couple: 8, crm_existing_family: 6, cross_year_frequency: '5├ùyears', surname_domain: 4 }[t] || '?'}</td></tr>`          ).join('\n')}        </tbody></table>        <div style="margin-top:10px;font-size:.7rem;color:var(--muted)">          <strong>Strategy:</strong> Edges with total weight ΓëÑ 3 form family groups via Union-Find clustering.          Multiple evidence types compound ΓÇö e.g., a pair in Family Universe (10) + Raw Entries (8) = 18 weight.        </div>      </div>    </div>  </div></div><!-- ΓòÉΓòÉΓòÉ MEMBERS ΓòÉΓòÉΓòÉ --><div class="tpanel" id="tp-members">  <input class="sbox" id="mSearch" placeholder="Search by name, email, phone, family..." oninput="filterM()">  <div style="font-size:.75rem;color:var(--muted);margin-bottom:10px">Showing <span id="mCount">${total}</span> of ${total}</div>  <div style="max-height:72vh;overflow-y:auto">    <table id="mTable"><thead><tr>      <th>#</th><th>Name</th><th>Email</th><th>Phone</th><th>Family</th><th>Years</th><th>Payments</th><th>Roles</th><th>Sources</th><th></th>    </tr></thead><tbody>      ${members.map((m, i) => `      <tr class="mrow" data-i="${i}" data-s="${norm(m.displayName + ' ' + m.email + ' ' + m.phone + ' ' + m.familyDisplayName + ' ' + m.householdDisplayName + ' ' + m.firstName + ' ' + m.lastName + ' ' + m.familyMembers.map(f => f.displayName || f.email).join(' ') + ' ' + m.householdMembers.map(f => f.displayName || f.email).join(' '))}">        <td style="color:var(--dim)">${i + 1}</td>        <td><strong>${m.displayName || m.email}</strong>${m.isECMember ? ' <span class="badge b-ec">EC</span>' : ''}${m.isActive ? '' : ' <span class="badge" style="background:rgba(239,68,68,.15);color:var(--red)">Inactive</span>'}</td>        <td style="font-size:.72rem;color:var(--muted)">${m.email}</td>        <td style="font-size:.75rem">${m.phone || '<span style="color:var(--dim)">ΓÇö</span>'}</td>        <td>${m.householdType !== 'individual' ? `<span class="b-fam" style="background:rgba(34,197,94,.1);color:#4ade80">${m.householdDisplayName}</span>` : m.familyDisplayName && m.familyType !== 'individual' ? `<span class="b-fam">${m.familyDisplayName}</span>` : '<span style="color:var(--dim)">ΓÇö</span>'}</td>        <td>${m.membershipYears.map(y => `<span class="b-year">${y}</span>`).join('') || '<span style="color:var(--dim)">ΓÇö</span>'}</td>        <td style="font-size:.75rem">${m.paymentRecords.length > 0 ? `$${m.totalPaid.toFixed(0)}` : '<span style="color:var(--dim)">ΓÇö</span>'}</td>        <td style="font-size:.75rem">${m.orgRoles.length > 0 ? m.orgRoles.length : '<span style="color:var(--dim)">ΓÇö</span>'}</td>        <td>${m.importSources.map(s => `<span class="badge ${s.includes('crm') && !s.includes('comprehensive') ? 'b-crm' : s.includes('google') ? 'b-google' : s.includes('family') ? 'b-family' : s.includes('membership') || s.includes('2526') ? 'b-member' : s.includes('audit') ? 'b-audit' : s.includes('jagriti') ? 'b-jagriti' : s.includes('admin') ? 'b-admin' : s === 'events' ? 'b-event' : 'b-other'}">${s.replace(/_/g, ' ')}</span>`).join('')}</td>        <td><i class="fas fa-chevron-down" style="color:var(--dim);cursor:pointer" onclick="toggleD(${i})"></i></td>      </tr>      <tr class="drow" id="dr-${i}" style="display:none"><td colspan="10">        <div class="detail on" data-member="${i}">          <div class="row">            <div class="col-md-4"><div class="dsec"><h6><i class="fas fa-user me-1"></i>Personal</h6><div class="dg" data-section="personal">              <div class="k">First Name</div><div class="v">${m.firstName || 'ΓÇö'}</div>              <div class="k">Last Name</div><div class="v">${m.lastName || 'ΓÇö'}</div>              <div class="k">Email</div><div class="v">${m.email}</div>              <div class="k">Phone</div><div class="v">${m.phone || 'ΓÇö'}</div>              <div class="k">Phone 2</div><div class="v">${m.phone2 || 'ΓÇö'}</div>              <div class="k">Gender</div><div class="v">${m.gender || 'ΓÇö'}</div>              <div class="k">DOB</div><div class="v">${m.dateOfBirth || 'ΓÇö'}</div>              <div class="k">Address</div><div class="v">${m.address || 'ΓÇö'}</div>              <div class="k">City/State</div><div class="v">${[m.city, m.state, m.zip].filter(Boolean).join(', ') || 'ΓÇö'}</div>              <div class="k">Profession</div><div class="v">${m.profession || 'ΓÇö'}</div>              <div class="k">Employer</div><div class="v">${m.employer || 'ΓÇö'}</div>              <div class="k">Education</div><div class="v">${m.education || 'ΓÇö'}</div>              <div class="k">Member ID</div><div class="v" style="font-size:.65rem">${m.memberId || 'ΓÇö'}</div>            </div></div></div>            <div class="col-md-4"><div class="dsec"><h6><i class="fas fa-home me-1"></i>Household Unit <span class="tier-badge tier-basic" style="font-size:.55rem">${m.householdType || 'individual'}</span></h6><div class="dg" data-section="household">              <div class="k">Household ID</div><div class="v" style="font-size:.65rem">${m.householdId || 'ΓÇö'}</div>              <div class="k">Type</div><div class="v">${m.householdType || 'ΓÇö'}</div>              <div class="k">Display Name</div><div class="v">${m.householdDisplayName || 'ΓÇö'}</div>              <div class="k">Role</div><div class="v">${m.householdRole || 'ΓÇö'}</div>              <div class="k">Spouse</div><div class="v">${m.householdMembers.map(f => f.displayName || f.email).join(', ') || 'None'}</div>              <div class="k">Kids (inferred)</div><div class="v">${m.inferredKids > 0 ? m.inferredKids + ' <span style="color:var(--muted);font-size:.65rem">(from event RSVP)</span>' : '0'}</div>              <div class="k">Membership</div><div class="v">${m.householdMembershipCategory ? `<span style="color:var(--accent)">${m.householdMembershipCategory}</span>` + (m.householdMembershipAmount ? ` ΓÇö $${m.householdMembershipAmount}` : '') : 'ΓÇö'}</div>              <div class="k">Years</div><div class="v">${m.householdYearActive && m.householdYearActive.length > 0 ? m.householdYearActive.map(y => `<span class="b-year">${y}</span>`).join(' ') : 'ΓÇö'}</div>            </div>            ${m.householdEvidence.length > 0 ? `<div style="margin-top:6px"><span style="font-size:.62rem;color:var(--dim)">Spouse Evidence (${m.householdEvidence.length}):</span><br>              ${m.householdEvidence.slice(0, 3).map(e => `<span class="ev-tag ev-${e.type}">${e.type.replace(/_/g, ' ')}</span>`).join(' ')}            </div>` : ''}            </div>            <div class="dsec"><h6><i class="fas fa-people-roof me-1"></i>Family Network <span style="font-size:.55rem;color:var(--dim)">(relationships)</span></h6><div class="dg" data-section="family">              <div class="k">Network ID</div><div class="v" style="font-size:.65rem">${m.familyId || 'ΓÇö'}</div>              <div class="k">Type</div><div class="v">${m.familyType || 'ΓÇö'}</div>              <div class="k">Display Name</div><div class="v">${m.familyDisplayName || 'ΓÇö'}</div>              <div class="k">Members</div><div class="v">${m.familyMembers.map(f => f.displayName || f.email).join('<br>') || 'None'}</div>            </div>            ${m.familyEvidence.length > 0 ? `<div style="margin-top:6px"><span style="font-size:.62rem;color:var(--dim)">Network Evidence (${m.familyEvidence.length}):</span><br>              ${m.familyEvidence.slice(0, 3).map(e => `<span class="ev-tag ev-${e.type}">${e.type.replace(/_/g, ' ')}: ${e.detail.substring(0, 40)}</span>`).join('<br>')}              ${m.familyEvidence.length > 3 ? `<br><span style="font-size:.58rem;color:var(--dim)">+${m.familyEvidence.length - 3} more</span>` : ''}</div>` : ''}            </div></div>            <div class="col-md-4"><div class="dsec"><h6><i class="fas fa-id-card me-1"></i>Membership</h6><div class="dg" data-section="membership">              <div class="k">Member Since</div><div class="v">${m.memberSince || 'ΓÇö'}</div>              <div class="k">Member Type</div><div class="v">${m.memberType}</div>              <div class="k">Years Active</div><div class="v">${m.membershipYears.join(', ') || 'ΓÇö'}</div>              <div class="k">Types</div><div class="v">${m.membershipTypes.join(', ') || 'ΓÇö'}</div>              <div class="k">EC Member</div><div class="v">${m.isECMember ? '<span style="color:var(--green)">Yes</span>' : 'No'}</div>              <div class="k">Active</div><div class="v">${m.isActive ? '<span style="color:var(--green)">Yes</span>' : '<span style="color:var(--red)">No</span>'}</div>            </div></div>            ${m.paymentRecords.length > 0 ? `<div class="dsec"><h6><i class="fas fa-credit-card me-1"></i>Payments (${m.paymentRecords.length})</h6>              ${m.paymentRecords.map(p => `<div style="font-size:.72rem"><span class="badge b-member">${p.year}</span> ${p.category} ΓÇö $${(p.amount || 0).toFixed(0)} <span style="color:var(--dim)">(${p.source})</span></div>`).join('')}              <div style="font-size:.72rem;font-weight:700;margin-top:4px;color:var(--accent)" class="calc-val" data-calc="totalPaid" data-m="${i}">Total: $${m.totalPaid.toFixed(0)}</div>            </div>` : ''}            ${m.orgRoles.length > 0 ? `<div class="dsec"><h6><i class="fas fa-id-badge me-1"></i>Org Roles (${m.orgRoles.length})</h6>              ${m.orgRoles.map(r => `<span class="badge b-admin">${r.term}: ${r.role}</span>`).join(' ')}</div>` : ''}            ${m.jagritiContributions.length > 0 ? `<div class="dsec"><h6><i class="fas fa-book me-1"></i>Cultural (${m.jagritiContributions.length})</h6>              ${m.jagritiContributions.map(j => `<span class="badge b-jagriti">Jagriti ${j.year}: ${j.type}${j.count > 1 ? ` (${j.count})` : ''}</span>`).join(' ')}              ${m.jagritiContributions.filter(j => j.comments).map(j => `<div style="font-size:.68rem;color:var(--muted);margin-top:2px">${j.comments}</div>`).join('')}            </div>` : ''}            ${m.eventAttendance.length > 0 || m.volunteerEvents.length > 0 ? `<div class="dsec"><h6><i class="fas fa-calendar-check me-1"></i>Events (${m.eventAttendance.length + m.volunteerEvents.length})</h6>              ${m.eventAttendance.map(e => `<div style="font-size:.72rem;margin-bottom:3px"><span class="badge" style="background:rgba(244,63,94,.15);color:#fb7185">${e.eventName}</span>                <span style="color:${e.rsvp === 'attending' || e.rsvp === 'Yes' ? 'var(--green)' : e.rsvp === 'not_attending' ? 'var(--red)' : 'var(--yellow)'}">${e.rsvp}</span>                ${e.totalAttendees > 0 ? `<span style="color:var(--muted)"> (${e.adults || e.totalAttendees} adults${e.kids ? ', ' + e.kids + ' kids' : ''})</span>` : ''}                ${e.amount > 0 ? `<span style="color:var(--accent)"> $${e.amount}</span>` : ''}                ${e.dietary && e.dietary !== 'unknown' ? `<span style="color:var(--muted)"> [${e.dietary}]</span>` : ''}                <span style="color:var(--dim);font-size:.6rem"> (${e.source})</span></div>`).join('')}              ${m.volunteerEvents.map(v => `<span class="badge" style="background:rgba(6,182,212,.15);color:#22d3ee;font-size:.6rem">${v.eventName}: ${v.role}</span>`).join(' ')}            </div>` : ''}            <div class="dsec"><h6><i class="fas fa-envelope me-1"></i>Communications</h6>              <div class="dg" data-section="communication"><div class="k">Total</div><div class="v">${m.communications}</div></div>            </div>            </div>          </div>          ${m.issues.length > 0 ? `<div class="dsec" style="margin-top:6px"><h6><i class="fas fa-triangle-exclamation me-1"></i>Issues (${m.issues.length})</h6>            ${m.issues.map(is => `<div class="issue-${is.severity[0]}">${is.severity === 'error' ? '≡ƒö┤' : is.severity === 'warning' ? '≡ƒƒí' : '≡ƒö╡'} [${is.area}] ${is.msg}</div>`).join('')}          </div>` : ''}          <div class="dsec" style="margin-top:6px"><h6><i class="fas fa-layer-group me-1"></i>Sources (${m.importSources.length})</h6>            ${m.importSources.map(s => `<span class="badge ${s.includes('crm') && !s.includes('comprehensive') ? 'b-crm' : s.includes('google') ? 'b-google' : s.includes('family') ? 'b-family' : s.includes('membership') || s.includes('2526') ? 'b-member' : s.includes('audit') ? 'b-audit' : s.includes('jagriti') ? 'b-jagriti' : s.includes('admin') ? 'b-admin' : s === 'events' ? 'b-event' : 'b-other'}">${s}</span>`).join(' ')}          </div>        </div>      </td></tr>`).join('\n')}    </tbody></table>  </div></div><!-- ΓòÉΓòÉΓòÉ FAMILIES (Household Units + Family Networks) ΓòÉΓòÉΓòÉ --><div class="tpanel" id="tp-families">  <!-- ΓöÇΓöÇ SECTION 1: HOUSEHOLD UNITS ΓöÇΓöÇ -->  <h5 style="color:var(--green);margin-bottom:8px"><i class="fas fa-home me-1"></i>${totalHouseholds} Household Units ΓÇö Membership Units  <button class="hh-btn hh-btn-primary" onclick="openFamilyAdmin()" style="float:right;font-size:.7rem" id="famAdminBtn"><i class="fas fa-users-cog me-1"></i>Manage Families</button>  </h5>  <p style="font-size:.72rem;color:var(--muted);margin-bottom:8px">    A <strong>Household Unit</strong> represents a membership billing unit: max 2 adults + dependents under 21.    Spouse pairs are identified from explicit evidence (XLSX couple entries, raw name co-occurrence).    Kid counts are inferred from event RSVP data.  </p>  <div style="font-size:.75rem;color:var(--muted);margin-bottom:12px">    <span class="badge b-family">${coupleHouseholds} Couples</span>    <span class="badge" style="background:rgba(34,197,94,.15);color:#4ade80">${familyHouseholds} Families (w/ kids)</span>    <span class="badge b-crm">${individualHouseholds} Individuals</span>    ${householdsWithKids > 0 ? `<span class="badge" style="background:rgba(251,191,36,.15);color:#fbbf24">${householdsWithKids} with inferred kids (${totalInferredKids} total)</span>` : ''}  </div>  <input class="sbox" id="hhSearch" placeholder="Search households..." oninput="filterHH()">  <div style="max-height:40vh;overflow-y:auto;margin-bottom:20px">    ${[...households.entries()].filter(([,h]) => h.type !== 'individual').sort((a, b) => b[1].totalSpouseWeight - a[1].totalSpouseWeight).map(([hhId, hh], i) => {        const hhMembers = [...hh.members].map(e => universe.get(e)).filter(Boolean);        const allYears = [...new Set(hhMembers.flatMap(m => m.membershipYears))].sort();        return `<div class="fam-card hhrow" data-s="${norm(hh.displayName + ' ' + [...hh.members].join(' '))}">          <div style="display:flex;justify-content:space-between;align-items:start">            <div><h6><i class="fas fa-${hh.type === 'couple' ? 'heart' : 'house'} me-1" style="color:var(--green)"></i>${hh.displayName}              <span class="badge" style="background:rgba(34,197,94,.15);color:#4ade80">${hh.type}</span>              <span style="font-size:.6rem;color:var(--dim)">${hhId}</span>              ${hh.inferredKids > 0 ? `<span class="badge" style="background:rgba(251,191,36,.15);color:#fbbf24;font-size:.55rem">≡ƒæ╢ ${hh.inferredKids} kids (inferred)</span>` : ''}              ${hh.membershipCategory ? `<span class="badge" style="background:rgba(249,115,22,.15);color:var(--accent);font-size:.55rem">≡ƒÆ│ ${hh.membershipCategory} ΓÇö $${hh.membershipAmount}</span>` : ''}            </h6></div>            <div>${allYears.map(y => `<span class="b-year">${y}</span>`).join('')}</div>          </div>          <div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:6px">            ${hhMembers.map((m, idx) => `<div style="background:var(--bg2);border:1px solid ${idx === 0 ? 'var(--green)' : 'var(--line)'};border-radius:6px;padding:6px 10px;font-size:.75rem;min-width:200px">              <strong>${m.displayName}</strong> <span style="font-size:.6rem;color:var(--dim)">${idx === 0 ? '(primary)' : '(spouse)'}</span><br>              <span style="color:var(--muted);font-size:.68rem">${m.email}</span>              ${m.phone ? `<br><span style="font-size:.68rem">≡ƒô▒${m.phone}</span>` : ''}            </div>`).join('')}          </div>          ${hh.spouseEvidence.length > 0 ? `<div style="margin-top:4px;font-size:.62rem;color:var(--dim)">            Spouse evidence (weight: ${hh.totalSpouseWeight}): ${hh.spouseEvidence.slice(0, 3).map(e => `<span class="ev-tag ev-${e.type}">${e.type.replace(/_/g, ' ')}</span>`).join(' ')}          </div>` : ''}        </div>`;    }).join('\n')}  </div>  <!-- ΓöÇΓöÇ SECTION 2: FAMILY NETWORKS ΓöÇΓöÇ -->  <h5 style="color:var(--accent);margin-bottom:8px;margin-top:20px;border-top:1px solid var(--line);padding-top:16px">    <i class="fas fa-people-roof me-1"></i>${totalFamilies} Family Networks ΓÇö Relationships  </h5>  <p style="font-size:.72rem;color:var(--muted);margin-bottom:8px">    A <strong>Family Network</strong> shows broader family connections (siblings, parents, relatives).     These are informational relationships ΓÇö NOT membership billing units.    Groups are capped at 6 members to prevent surname-chain explosion.  </p>  <div style="font-size:.75rem;color:var(--muted);margin-bottom:12px">    <span class="badge b-family">${coupleFams} Couples</span>    <span class="badge b-member">${familyFams} Families (3+)</span>    <span class="badge b-crm">${individualFams} Individuals</span>  </div>  <input class="sbox" id="fSearch" placeholder="Search family networks..." oninput="filterF()">  <div style="max-height:50vh;overflow-y:auto">    ${[...families.entries()].sort((a, b) => b[1].members.size - a[1].members.size).map(([fid, fam], i) => {        const fMembers = [...fam.members].map(e => universe.get(e)).filter(Boolean);        const allYears = [...new Set(fMembers.flatMap(m => m.membershipYears))].sort();        return `<div class="fam-card frow" data-s="${norm(fam.displayName + ' ' + [...fam.members].join(' ') + ' ' + fam.surnames.join(' '))}">          <div style="display:flex;justify-content:space-between;align-items:start">            <div><h6><i class="fas fa-${fam.type === 'couple' ? 'heart' : fam.type === 'family' ? 'house' : 'user'} me-1"></i>${fam.displayName}              <span class="badge b-family">${fam.type}</span>              <span style="font-size:.6rem;color:var(--dim)">${fid}</span></h6></div>            <div>${allYears.map(y => `<span class="b-year">${y}</span>`).join('')}</div>          </div>          <div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:6px">            ${fMembers.map(m => `<div style="background:var(--bg2);border:1px solid var(--line);border-radius:6px;padding:6px 10px;font-size:.75rem;min-width:200px">              <strong>${m.displayName}</strong><br>              <span style="color:var(--muted);font-size:.68rem">${m.email}</span>              ${m.phone ? `<br><span style="font-size:.68rem">≡ƒô▒${m.phone}</span>` : ''}              ${m.orgRoles.length > 0 ? `<br><span class="badge b-admin" style="font-size:.55rem">${m.orgRoles[0].role}</span>` : ''}            </div>`).join('')}          </div>          <div style="margin-top:6px">            <span style="font-size:.62rem;color:var(--dim)">Evidence (${fam.evidence.length}, weight: ${fam.totalWeight}):</span>            ${fam.evidence.slice(0, 4).map(e => `<span class="ev-tag ev-${e.type}">${e.type.replace(/_/g, ' ')}</span>`).join('')}            ${fam.evidence.length > 4 ? `<span style="font-size:.58rem;color:var(--dim)">+${fam.evidence.length - 4}</span>` : ''}          </div>        </div>`;    }).join('\n')}  </div></div><!-- ΓòÉΓòÉΓòÉ RECONCILIATION ΓòÉΓòÉΓòÉ --><div class="tpanel" id="tp-recon">  <h5 style="color:var(--accent);margin-bottom:16px"><i class="fas fa-arrows-rotate me-1"></i>Reconciliation Matrix</h5>  <p style="font-size:.78rem;color:var(--muted)">Shows how each CRM dimension was reconciled across sources, including conflicts and gaps.</p>  <div class="row g-3">    ${Object.entries(dimStats).map(([dim, s]) => {        const pct = total > 0 ? (s.complete / total * 100).toFixed(0) : 0;        const colors = { personal: '#3b82f6', family: '#a855f7', membership: '#22c55e', payment: '#f97316', orgRole: '#eab308', volunteer: '#06b6d4', cultural: '#ec4899', communication: '#14b8a6', events: '#f43f5e' };        const icons = { personal: 'user', family: 'people-roof', membership: 'id-card', payment: 'credit-card', orgRole: 'id-badge', volunteer: 'hand-holding-heart', cultural: 'music', communication: 'envelope', events: 'calendar-check' };        const dimMembers = members.filter(m => m.reconciliation[dim] && m.reconciliation[dim].length > 0);        const conflicts = dim === 'personal' ? members.filter(m => m.reconciliation.personal.some(r => r.action === 'conflict')).length : 0;        return `<div class="col-md-3"><div style="background:var(--card);border:1px solid var(--line);border-radius:10px;padding:14px">          <div style="display:flex;justify-content:space-between;align-items:center">            <h6 style="color:${colors[dim]};font-size:.8rem;margin:0"><i class="fas fa-${icons[dim]} me-1"></i>${dim.charAt(0).toUpperCase() + dim.slice(1)}</h6>            <span style="font-size:1.1rem;font-weight:800;color:${colors[dim]}">${pct}%</span>          </div>          <div class="dim-bar" style="margin:6px 0"><div class="dim-fill" style="width:${pct}%;background:${colors[dim]}"></div></div>          <div style="font-size:.7rem;color:var(--muted)">${s.complete}/${total} members have data</div>          ${conflicts > 0 ? `<div style="font-size:.68rem;color:var(--yellow);margin-top:3px">ΓÜá ${conflicts} members have conflicts</div>` : ''}          <div style="font-size:.68rem;color:var(--dim);margin-top:3px">${dimMembers.length} reconciliation entries</div>        </div></div>`;    }).join('\n')}  </div>  <div style="margin-top:16px;background:var(--bg2);border:1px solid var(--line);border-radius:10px;padding:14px">    <h6 style="color:var(--yellow);font-size:.8rem"><i class="fas fa-exclamation-triangle me-1"></i>Conflicts Requiring Manual Review</h6>    <div style="max-height:300px;overflow-y:auto">      ${members.filter(m => m.reconciliation.personal.some(r => r.action === 'conflict')).map(m => {          const conflicts = m.reconciliation.personal.filter(r => r.action === 'conflict');          return `<div class="conflict"><strong>${m.displayName}</strong> (${m.email})<br>            ${conflicts.map(c => `<span style="color:var(--muted)">${c.field}:</span> <span style="color:var(--red)">${c.oldValue}</span> ΓåÉ <span style="color:var(--green)">${c.newValue}</span> <span style="color:var(--dim)">(${c.source})</span>`).join('<br>')}          </div>`;      }).join('\n') || '<span style="color:var(--green)">No conflicts found!</span>'}    </div>  </div></div><!-- ΓòÉΓòÉΓòÉ DATA GAPS ΓòÉΓòÉΓòÉ --><div class="tpanel" id="tp-gaps">  <h5 style="color:var(--accent);margin-bottom:16px"><i class="fas fa-triangle-exclamation me-1"></i>Data Gaps & Issues</h5>  <div class="row g-3">    <div class="col-md-6"><div style="background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px">      <h6 style="color:var(--yellow)"><i class="fas fa-phone-slash me-1"></i>Missing Phone (${total - withPhone})</h6>      <div style="max-height:250px;overflow-y:auto;font-size:.75rem">        ${members.filter(m => !m.phone).slice(0, 50).map(m => `<div style="padding:2px 0;border-bottom:1px solid var(--line)">${m.displayName} <span style="color:var(--dim)">(${m.email})</span></div>`).join('\n')}      </div></div></div>    <div class="col-md-6"><div style="background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px">      <h6 style="color:var(--red)"><i class="fas fa-user-slash me-1"></i>Name Issues (${noName})</h6>      <div style="max-height:250px;overflow-y:auto;font-size:.75rem">        ${members.filter(m => !m.firstName || m.firstName === m.email).map(m => `<div style="padding:2px 0;border-bottom:1px solid var(--line)">${m.email}</div>`).join('\n') || '<span style="color:var(--green)">All names resolved!</span>'}      </div></div></div>    <div class="col-md-6"><div style="background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px">      <h6 style="color:var(--cyan)"><i class="fas fa-wallet me-1"></i>No Payment Records (${total - withPayment})</h6>      <div style="max-height:250px;overflow-y:auto;font-size:.75rem">        ${members.filter(m => m.paymentRecords.length === 0).slice(0, 50).map(m => `<div style="padding:2px 0;border-bottom:1px solid var(--line)">${m.displayName} <span style="color:var(--dim)">${m.membershipYears.join(', ') || 'no years'}</span></div>`).join('\n')}      </div></div></div>    <div class="col-md-6"><div style="background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px">      <h6 style="color:var(--yellow)"><i class="fas fa-file-excel me-1"></i>Unmatched XLSX Names (${unmatchedNames.length})</h6>      <div style="max-height:250px;overflow-y:auto;font-size:.75rem">        ${unmatchedNames.map(m => `<div style="padding:2px 0;border-bottom:1px solid var(--line)">${m.name} <span style="color:var(--dim)">${m.category} ΓÇö $${m.amount}</span></div>`).join('\n') || '<span style="color:var(--green)">All matched!</span>'}      </div></div></div>  </div></div><!-- ΓòÉΓòÉΓòÉ FAMILY EVIDENCE ΓòÉΓòÉΓòÉ --><div class="tpanel" id="tp-evidence">  <h5 style="color:var(--accent);margin-bottom:16px"><i class="fas fa-link me-1"></i>Family Evidence Graph</h5>  <p style="font-size:.78rem;color:var(--muted);margin-bottom:12px">    Shows the evidence edges that drive intelligent family grouping. Pairs with combined weight ΓëÑ 3 are grouped into families.    <strong>9 evidence layers</strong> provide signals: pre-built families, co-occurrence in XLSX, couple notation, validated mappings, CRM links, surname+domain, and cross-year frequency.  </p>  <div style="max-height:70vh;overflow-y:auto">    <table><thead><tr><th>Person A</th><th>Person B</th><th>Weight</th><th>Evidence</th></tr></thead><tbody>      ${[...familyGraph.edges.values()].sort((a, b) => b.weight - a.weight).slice(0, 100).map(e => {          const pA = familyGraph.nodes.get(e.a), pB = familyGraph.nodes.get(e.b);          return `<tr>            <td>${pA ? pA.firstName + ' ' + pA.lastName : e.a} <span style="color:var(--dim);font-size:.65rem">${e.a}</span></td>            <td>${pB ? pB.firstName + ' ' + pB.lastName : e.b} <span style="color:var(--dim);font-size:.65rem">${e.b}</span></td>            <td style="font-weight:700;color:${e.weight >= 10 ? 'var(--green)' : e.weight >= 5 ? 'var(--yellow)' : 'var(--muted)'}">${e.weight}</td>            <td>${e.evidence.map(ev => `<span class="ev-tag ev-${ev.type}">${ev.type.replace(/_/g, ' ')}</span>`).join(' ')}</td>          </tr>`;      }).join('\n')}    </tbody></table>  </div></div><!-- ΓòÉΓòÉΓòÉ EVENTS ΓòÉΓòÉΓòÉ --><div class="tpanel" id="tp-events">  <h5 style="color:var(--accent);margin-bottom:16px"><i class="fas fa-calendar-check me-1"></i>Event Attendance & Evite Responses</h5>  <p style="font-size:.78rem;color:var(--muted);margin-bottom:12px">    Tracks member attendance across BANF events ΓÇö XLSX evite lists, live Evite API RSVPs, and volunteer/POC roles.  </p>  ${(() => {      // Aggregate events      const eventMap = {};      for (const m of members) {          for (const ea of m.eventAttendance) {              if (!eventMap[ea.eventName]) eventMap[ea.eventName] = { name: ea.eventName, date: ea.eventDate, attending: 0, notAttending: 0, unclear: 0, totalHeads: 0, totalKids: 0, totalAmount: 0, attendees: [] };              const ev = eventMap[ea.eventName];              if (ea.rsvp === 'attending' || ea.rsvp === 'Yes') { ev.attending++; ev.totalHeads += (ea.adults || ea.totalAttendees || 1); ev.totalKids += (ea.kids || 0); }              else if (ea.rsvp === 'not_attending') ev.notAttending++;              else ev.unclear++;              ev.totalAmount += (ea.amount || 0);              ev.attendees.push({ name: m.displayName, email: m.email, rsvp: ea.rsvp, adults: ea.adults, kids: ea.kids, totalAttendees: ea.totalAttendees, dietary: ea.dietary, amount: ea.amount, source: ea.source });          }      }      // Volunteer summary      const volMap = {};      for (const m of members) {          for (const v of m.volunteerEvents) {              if (!volMap[v.eventName]) volMap[v.eventName] = [];              volMap[v.eventName].push({ name: m.displayName, role: v.role });          }      }      const events = Object.values(eventMap);      return `  <div class="row g-3 mb-3">    <div class="col-6 col-md-2"><div class="stat"><div class="n">${events.length}</div><div class="l">Events Tracked</div></div></div>    <div class="col-6 col-md-2"><div class="stat"><div class="n">${events.reduce((s,e) => s + e.attending, 0)}</div><div class="l">Total Attending</div></div></div>    <div class="col-6 col-md-2"><div class="stat"><div class="n">${events.reduce((s,e) => s + e.totalHeads + e.totalKids, 0)}</div><div class="l">Total Headcount</div></div></div>    <div class="col-6 col-md-2"><div class="stat"><div class="n">${withEvents}</div><div class="l">Members w/Events</div></div></div>    <div class="col-6 col-md-2"><div class="stat"><div class="n">$${events.reduce((s,e) => s + e.totalAmount, 0).toFixed(0)}</div><div class="l">Event Revenue</div></div></div>    <div class="col-6 col-md-2"><div class="stat"><div class="n">${Object.values(volMap).reduce((s,v) => s + v.length, 0)}</div><div class="l">Volunteer Roles</div></div></div>  </div>  ${events.map(evt => `  <div class="fam-card" style="margin-bottom:12px">    <div style="display:flex;justify-content:space-between;align-items:center">      <h6 style="margin:0"><i class="fas fa-calendar me-1" style="color:#f43f5e"></i>${evt.name}        <span style="font-size:.65rem;color:var(--dim)">${evt.date || ''}</span></h6>      <div>        <span class="badge" style="background:rgba(34,197,94,.15);color:var(--green)">${evt.attending} attending</span>        <span class="badge" style="background:rgba(239,68,68,.15);color:var(--red)">${evt.notAttending} declined</span>        ${evt.unclear > 0 ? '<span class="badge" style="background:rgba(234,179,8,.15);color:var(--yellow)">' + evt.unclear + ' unclear</span>' : ''}      </div>    </div>    <div style="font-size:.72rem;color:var(--muted);margin-top:4px">      Headcount: ${evt.totalHeads} adults${evt.totalKids > 0 ? ', ' + evt.totalKids + ' kids' : ''} | Revenue: $${evt.totalAmount.toFixed(0)}      ${volMap[evt.name] ? ' | Volunteers: ' + volMap[evt.name].map(v => v.name + ' (' + v.role + ')').join(', ') : ''}    </div>    <div style="margin-top:8px;max-height:250px;overflow-y:auto">      <table><thead><tr><th>Name</th><th>RSVP</th><th>Adults</th><th>Kids</th><th>Dietary</th><th>Amount</th><th>Source</th></tr></thead><tbody>        ${evt.attendees.sort((a,b) => {            const order = { attending: 0, Yes: 0, not_attending: 1, unclear: 2 };            return (order[a.rsvp] ?? 3) - (order[b.rsvp] ?? 3);        }).map(a => '<tr>'          + '<td>' + a.name + ' <span style="color:var(--dim);font-size:.6rem">' + a.email + '</span></td>'          + '<td><span style="color:' + (a.rsvp === 'attending' || a.rsvp === 'Yes' ? 'var(--green)' : a.rsvp === 'not_attending' ? 'var(--red)' : 'var(--yellow)') + '">' + a.rsvp + '</span></td>'          + '<td>' + (a.adults || a.totalAttendees || 'ΓÇö') + '</td>'          + '<td>' + (a.kids || 'ΓÇö') + '</td>'          + '<td>' + (a.dietary && a.dietary !== 'unknown' ? a.dietary : 'ΓÇö') + '</td>'          + '<td>' + (a.amount > 0 ? '$' + a.amount : 'ΓÇö') + '</td>'          + '<td><span style="font-size:.6rem;color:var(--dim)">' + a.source + '</span></td>'          + '</tr>').join('')}      </tbody></table>    </div>  </div>`).join('\\n')}  ${Object.keys(volMap).length > 0 ? '<div class="fam-card"><h6 style="color:var(--cyan)"><i class="fas fa-hand-holding-heart me-1"></i>Volunteer Summary</h6><table><thead><tr><th>Event</th><th>Name</th><th>Role</th></tr></thead><tbody>' + Object.entries(volMap).flatMap(([evt, vols]) => vols.map(v => '<tr><td>' + evt + '</td><td>' + v.name + '</td><td>' + v.role + '</td></tr>')).join('') + '</tbody></table></div>' : ''}  `;  })()}</div><!-- ΓòÉΓòÉΓòÉ RELATIONSHIPS ΓòÉΓòÉΓòÉ --><div class="tpanel" id="tp-relationships">  <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;flex-wrap:wrap;gap:8px">    <h5 style="color:var(--accent);margin:0"><i class="fas fa-heart me-1"></i>Relationship Management System</h5>    <div style="display:flex;gap:6px;align-items:center" id="relAdminBtns">      <button class="hh-btn hh-btn-primary" onclick="openRelAdmin()" title="Admin: Add/Edit/Delete relationships"><i class="fas fa-users-cog me-1"></i>Manage Relationships</button>      <button class="hh-btn" onclick="exportRelJSON()" title="Export relationships as JSON"><i class="fas fa-download me-1"></i>Export</button>      <button class="hh-btn" onclick="importRelJSON()" title="Import relationships from JSON"><i class="fas fa-upload me-1"></i>Import</button>    </div>  </div>  <!-- Relationship Taxonomy Reference -->  <div style="background:var(--bg2);border:1px solid var(--line);border-radius:10px;padding:14px;margin-bottom:16px">    <h6 style="color:var(--cyan);font-size:.78rem;margin-bottom:8px"><i class="fas fa-book me-1"></i>Relationship Taxonomy ΓÇö Definitions</h6>    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:8px;font-size:.72rem">      <div style="padding:4px 8px;background:var(--card);border-radius:6px;border-left:3px solid #ec4899">≡ƒÆì <strong>Husband</strong> ΓÇö Male spouse in a married couple</div>      <div style="padding:4px 8px;background:var(--card);border-radius:6px;border-left:3px solid #ec4899">≡ƒÆì <strong>Wife</strong> ΓÇö Female spouse in a married couple</div>      <div style="padding:4px 8px;background:var(--card);border-radius:6px;border-left:3px solid #3b82f6">≡ƒæ¿ <strong>Father</strong> ΓÇö Male parent of a child</div>      <div style="padding:4px 8px;background:var(--card);border-radius:6px;border-left:3px solid #a855f7">≡ƒæ⌐ <strong>Mother</strong> ΓÇö Female parent of a child</div>      <div style="padding:4px 8px;background:var(--card);border-radius:6px;border-left:3px solid #22c55e">≡ƒæª <strong>Son</strong> ΓÇö Male child of a parent</div>      <div style="padding:4px 8px;background:var(--card);border-radius:6px;border-left:3px solid #14b8a6">≡ƒæº <strong>Daughter</strong> ΓÇö Female child of a parent</div>      <div style="padding:4px 8px;background:var(--card);border-radius:6px;border-left:3px solid #eab308">≡ƒæ¼ <strong>Brother</strong> ΓÇö Male sibling sharing parent(s)</div>      <div style="padding:4px 8px;background:var(--card);border-radius:6px;border-left:3px solid #f97316">≡ƒæ¡ <strong>Sister</strong> ΓÇö Female sibling sharing parent(s)</div>      <div style="padding:4px 8px;background:var(--card);border-radius:6px;border-left:3px solid #06b6d4">≡ƒæ┤ <strong>Father-in-Law</strong> ΓÇö Father of one's spouse</div>      <div style="padding:4px 8px;background:var(--card);border-radius:6px;border-left:3px solid #8b5cf6">≡ƒæ╡ <strong>Mother-in-Law</strong> ΓÇö Mother of one's spouse</div>      <div style="padding:4px 8px;background:var(--card);border-radius:6px;border-left:3px solid #64748b">≡ƒñ╡ <strong>Son-in-Law</strong> ΓÇö Husband of one's child</div>      <div style="padding:4px 8px;background:var(--card);border-radius:6px;border-left:3px solid #64748b">≡ƒæ░ <strong>Daughter-in-Law</strong> ΓÇö Wife of one's child</div>      <div style="padding:4px 8px;background:var(--card);border-radius:6px;border-left:3px solid #94a3b8">≡ƒæÑ <strong>Relative</strong> ΓÇö Other family relationship</div>    </div>  </div>  <!-- Stats -->  <div class="row g-3 mb-3">    <div class="col-6 col-md-2"><div class="stat"><div class="n">${totalRels}</div><div class="l">Relationships</div></div></div>    <div class="col-6 col-md-2"><div class="stat"><div class="n">${membersWithRels.size}</div><div class="l">Members Linked</div></div></div>    <div class="col-6 col-md-2"><div class="stat"><div class="n">${Math.floor(spouseRels / 2) || spouseRels}</div><div class="l">Spouse Pairs</div></div></div>    <div class="col-6 col-md-2"><div class="stat"><div class="n">${parentChildRels}</div><div class="l">Parent-Child</div></div></div>    <div class="col-6 col-md-2"><div class="stat"><div class="n">${siblingRels}</div><div class="l">Siblings</div></div></div>    <div class="col-6 col-md-2"><div class="stat"><div class="n">${total - membersWithRels.size}</div><div class="l">No Relationships</div></div></div>  </div>  <!-- Search Interface -->  <div style="background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px;margin-bottom:16px">    <h6 style="color:var(--accent);font-size:.82rem;margin-bottom:10px"><i class="fas fa-search me-1"></i>Find Member Relationships</h6>    <input class="sbox" id="relSearch" placeholder="Search by name, email, phone, or signature pattern..." oninput="searchRelationships()" autocomplete="off">    <div id="relSearchResults" style="margin-top:10px"></div>  </div>  <!-- Relationship Detail Panel -->  <div id="relDetailPanel" style="display:none;background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px;margin-bottom:16px">  </div>  <!-- Members Missing Relationships -->  <div style="background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px;margin-bottom:16px">    <h6 style="color:var(--yellow);font-size:.82rem;margin-bottom:10px"><i class="fas fa-user-plus me-1"></i>Members Without Relationships (${total - membersWithRels.size})</h6>    <p style="font-size:.72rem;color:var(--muted);margin-bottom:8px">These members have no detected family relationships. Search above or use Admin to add.</p>    <div style="max-height:250px;overflow-y:auto;font-size:.75rem">      ${members.filter(m => !membersWithRels.has(m.email)).slice(0, 60).map(m => {          const sig = relData.signatures.get(m.email);          return `<div style="padding:4px 0;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;cursor:pointer" onclick="showRelDetail('${m.email}')">            <div><strong>${m.displayName || m.email}</strong> <span style="color:var(--dim);font-size:.65rem">${m.email}</span></div>            <div style="font-size:.62rem;color:var(--dim)">${sig ? sig.signatureShort : ''}</div>          </div>`;      }).join('\n')}    </div>  </div>  <!-- Inference Agents Summary -->  <div style="background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px">    <h6 style="color:var(--purple);font-size:.82rem;margin-bottom:10px"><i class="fas fa-robot me-1"></i>Inference Agent Results</h6>    <div class="row g-3">      <div class="col-md-4"><div style="background:var(--bg2);border-radius:8px;padding:12px;border-left:3px solid #ec4899">        <div style="font-size:.72rem;font-weight:700;color:#ec4899;margin-bottom:4px"><i class="fas fa-ring me-1"></i>Agent 1: Spouse Detection</div>        <div style="font-size:.68rem;color:var(--muted)">Sources: Household pairs, Da/Di honorifics, +/& notation</div>        <div style="font-size:.85rem;font-weight:800;color:var(--accent);margin-top:4px">${spouseRels} relationships (90% confidence)</div>      </div></div>      <div class="col-md-4"><div style="background:var(--bg2);border-radius:8px;padding:12px;border-left:3px solid #3b82f6">        <div style="font-size:.72rem;font-weight:700;color:#3b82f6;margin-bottom:4px"><i class="fas fa-sitemap me-1"></i>Agent 2: Parent-Child</div>        <div style="font-size:.68rem;color:var(--muted)">Sources: Family groups &gt;2, EB-Family, event kids</div>        <div style="font-size:.85rem;font-weight:800;color:var(--accent);margin-top:4px">${parentChildRels} relationships (55% confidence)</div>      </div></div>      <div class="col-md-4"><div style="background:var(--bg2);border-radius:8px;padding:12px;border-left:3px solid #eab308">        <div style="font-size:.72rem;font-weight:700;color:#eab308;margin-bottom:4px"><i class="fas fa-people-arrows me-1"></i>Agent 3: Sibling</div>        <div style="font-size:.68rem;color:var(--muted)">Sources: Same surname in family group, not spouse</div>        <div style="font-size:.85rem;font-weight:800;color:var(--accent);margin-top:4px">${siblingRels} relationships (40% confidence)</div>      </div></div>    </div>    <div style="margin-top:10px;font-size:.68rem;color:var(--muted)">      <i class="fas fa-info-circle me-1"></i><strong>Note:</strong> All inferred relationships should be reviewed by admin.      Spouse pairs are detected with highest confidence. Parent-child and sibling relationships are inferred from family group structure      and may need manual correction. Use "Manage Relationships" to review, correct, or add missing relationships.    </div>  </div></div><!-- ΓòÉΓòÉΓòÉ PLAN ΓòÉΓòÉΓòÉ --><div class="tpanel" id="tp-plan">  <h5 style="color:var(--accent);margin-bottom:16px"><i class="fas fa-clipboard-list me-1"></i>Complete CRM Reconciliation Plan</h5>  <div style="display:grid;gap:10px">    <div class="fam-card"><span class="badge b-google" style="float:right">Γ£ô DONE</span><h6>Step 1: Data Source Inventory</h6><p style="font-size:.75rem;color:var(--muted)">Identified 10 data sources: CRM API (179), Google Contacts (165), Family Universe v3 (105 families, 226 individuals, 288 raw entries), Membership 2025-26 XLSX (80 actual, 37 couples), Family Fix Mapping (135 families), Member Audit (168), CRM Comprehensive (165), Admin Report 25-26 (164 contacts), Jagriti 2022+2023 (46 contributors), Report Family Mapping (58 families).</p></div>    <div class="fam-card"><span class="badge b-google" style="float:right">Γ£ô DONE</span><h6>Step 2: Intelligent Family Grouping</h6><p style="font-size:.75rem;color:var(--muted)">Built evidence graph with 9 layers (${familyGraph.edges.size} edges). Used Union-Find clustering with threshold ΓëÑ 3 to create ${totalFamilies} family groups: ${coupleFams} couples, ${familyFams} families, ${individualFams} individuals. Evidence types: pre-built families, raw entry co-occurrence, XLSX couple notation, validated mappings, CRM links, surname+domain, cross-year frequency.</p></div>    <div class="fam-card"><span class="badge b-google" style="float:right">Γ£ô DONE</span><h6>Step 3: 9-Dimension Reconciliation</h6><p style="font-size:.75rem;color:var(--muted)">Reconciled all ${total} members across Personal, Family, Membership, Payment, Org Roles, Volunteer, Cultural, Communications, and Events. Detected ${members.filter(m => m.reconciliation.personal.some(r => r.action === 'conflict')).length} field conflicts across sources. Payment data matched ${sources._xlsxMatched || 0}/${(sources._xlsxMatched || 0) + (sources._xlsxUnmatched || 0)} XLSX entries.</p></div>    <div class="fam-card"><span class="badge b-google" style="float:right">Γ£ô DONE</span><h6>Step 4: Data Quality Analysis</h6><p style="font-size:.75rem;color:var(--muted)">Identified gaps: ${total - withPhone} missing phones, ${noName} name issues, ${total - withPayment} no payments, ${total - withComms} no communications, ${total - withOrgRole} no org roles, ${total - withJagriti} no cultural data, ${unmatchedNames.length} unmatched XLSX names.</p></div>    <div class="fam-card"><span class="badge b-member" style="float:right">PENDING</span><h6>Step 5: Push Enrichment to CRM</h6><p style="font-size:.75rem;color:var(--muted)">Run with --enrich to push: phone numbers from Google Contacts, corrected names, family group assignments, membership year history. Estimated updates: ${members.filter(m => m.raw.crm && (!m.raw.crm.phone && m.phone)).length} phone enrichments, ${members.filter(m => m.raw.crm && m.raw.crm.firstName === m.raw.crm.email).length} name fixes.</p></div>    <div class="fam-card"><span class="badge b-member" style="float:right">PENDING</span><h6>Step 6: Payment History Import</h6><p style="font-size:.75rem;color:var(--muted)">Import all XLSX payment records into Payments collection. Link by member email/familyId. Historical data: 2022-23 through 2025-26 from Family Universe + Membership XLSX.</p></div>    <div class="fam-card"><span class="badge b-google" style="float:right">Γ£ô DONE</span><h6>Step 7: Event Participation Import</h6><p style="font-size:.75rem;color:var(--muted)">Imported event data from: Saraswati Puja 2026 (XLSX evite list, 74 entries), Bosonto Utsob 2026 (Live Evite API, 37 RSVPs), volunteer/POC data from Kali Puja 2025, Saraswati Puja 2026, Winter Picnic 2026. ${withEvents} members now have event records.</p></div>    <div class="fam-card"><span class="badge b-audit" style="float:right">ONGOING</span><h6>Step 8: Google Drive Document Scan</h6><p style="font-size:.75rem;color:var(--muted)">Use /gdrive_search and /gdrive_list APIs to find: annual member lists, payment receipts, EC meeting minutes, event attendance sheets. Cross-reference with CRM records.</p></div>    <div class="fam-card"><span class="badge b-audit" style="float:right">ONGOING</span><h6>Step 9: Family Verification</h6><p style="font-size:.75rem;color:var(--muted)">Stakeholders review the Families tab in this report to verify family groupings. Report any incorrect groupings for manual correction.</p></div>    <div class="fam-card"><span class="badge b-other" style="float:right">FUTURE</span><h6>Step 10: Annual Refresh Pipeline</h6><p style="font-size:.75rem;color:var(--muted)">Each year: ingest new membership XLSX, update payment records, refresh org roles, import new event data. Maintain the member universe as the single source of truth.</p></div>  </div></div><!-- ΓòÉΓòÉΓòÉ SOURCES ΓòÉΓòÉΓòÉ --><div class="tpanel" id="tp-sources">  <h5 style="color:var(--accent);margin-bottom:16px"><i class="fas fa-layer-group me-1"></i>Data Source Inventory</h5>  <div class="row g-3">    <div class="col-md-6"><div style="background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px">      <h6 style="color:var(--blue)"><i class="fas fa-cloud me-1"></i>Live APIs</h6>      <table><thead><tr><th>Endpoint</th><th>Records</th></tr></thead><tbody>        <tr><td>GET /crm_members</td><td>${sources.crmMembers.length}</td></tr>        <tr><td>GET /crm_dashboard</td><td>180 total</td></tr>        <tr><td>GET /crm_org_roles</td><td>128</td></tr>        <tr><td>GET /crm_member_comms</td><td>212 total</td></tr>      </tbody></table>    </div></div>    <div class="col-md-6"><div style="background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px">      <h6 style="color:var(--green)"><i class="fas fa-file-code me-1"></i>JSON Files</h6>      <table><thead><tr><th>Source</th><th>Members</th><th>Coverage</th></tr></thead><tbody>        ${Object.entries(sourceCount).sort((a, b) => b[1] - a[1]).map(([s, c]) =>            `<tr><td><span class="badge ${s.includes('crm') && !s.includes('comprehensive') ? 'b-crm' : s.includes('google') ? 'b-google' : s.includes('family') ? 'b-family' : s.includes('membership') || s.includes('2526') ? 'b-member' : s.includes('audit') ? 'b-audit' : s.includes('jagriti') ? 'b-jagriti' : s.includes('admin') ? 'b-admin' : s === 'events' ? 'b-event' : 'b-other'}">${s}</span></td><td>${c}</td><td>${(c / total * 100).toFixed(1)}%</td></tr>`        ).join('\n')}      </tbody></table>    </div></div>  </div></div></div><script>function showTab(id){document.querySelectorAll('.tpanel').forEach(t=>t.classList.remove('on'));document.querySelectorAll('.tab').forEach(b=>b.classList.remove('on'));document.getElementById('tp-'+id).classList.add('on');event.target.closest('.tab').classList.add('on')}function toggleD(i){const r=document.getElementById('dr-'+i);r.style.display=r.style.display==='none'?'':'none'}function filterM(){const q=document.getElementById('mSearch').value.toLowerCase();let c=0;document.querySelectorAll('.mrow').forEach(r=>{const ok=!q||r.dataset.s.includes(q);r.style.display=ok?'':'none';if(!ok)document.getElementById('dr-'+r.dataset.i).style.display='none';if(ok)c++});document.getElementById('mCount').textContent=c}function filterF(){const q=document.getElementById('fSearch').value.toLowerCase();document.querySelectorAll('.frow').forEach(r=>{r.style.display=!q||r.dataset.s.includes(q)?'':'none'})}function filterHH(){const q=document.getElementById('hhSearch').value.toLowerCase();document.querySelectorAll('.hhrow').forEach(r=>{r.style.display=!q||r.dataset.s.includes(q)?'':'none'})}</script><!-- ΓòÉΓòÉΓòÉ AUTH MODAL ΓòÉΓòÉΓòÉ --><div class="modal-overlay" id="authModal"><div class="modal-box" style="max-width:400px"><div class="modal-hdr"><h5><i class="fas fa-shield-halved me-1"></i>Admin Authentication</h5><button class="modal-close" onclick="closeModal('authModal')">&times;</button></div><div class="modal-body"><div class="edit-form"><label>Admin Email</label><input type="email" id="authEmail" placeholder="Enter your admin email..."><label>Password</label><input type="password" id="authPass" placeholder="Enter password..."><div style="margin-top:10px"><button class="btn-save" onclick="doLogin()"><i class="fas fa-right-to-bracket me-1"></i>Login</button><button class="btn-cancel" onclick="closeModal('authModal')">Cancel</button></div><div id="authMsg" style="margin-top:8px;font-size:.72rem"></div></div></div></div></div><!-- ΓòÉΓòÉΓòÉ FAMILY ADMIN MODAL ΓòÉΓòÉΓòÉ --><div class="modal-overlay" id="familyAdminModal"><div class="modal-box" style="max-width:960px;height:85vh"><div class="modal-hdr"><h5><i class="fas fa-users-cog me-1"></i>Family & Household Admin</h5><div style="display:flex;gap:6px;align-items:center"><button class="hh-btn" onclick="exportHouseholdJSON()"><i class="fas fa-download me-1"></i>Export</button><button class="hh-btn" onclick="importHouseholdJSON()"><i class="fas fa-upload me-1"></i>Import</button><button class="hh-btn hh-btn-primary" onclick="saveHouseholdChanges()"><i class="fas fa-save me-1"></i>Save</button><button class="modal-close" onclick="closeModal('familyAdminModal')">&times;</button></div></div><div class="modal-body" style="display:flex;gap:12px;height:calc(100% - 90px);padding:10px"><div style="flex:1;min-width:260px;overflow-y:auto;border-right:1px solid var(--line);padding-right:10px"><input class="sbox" id="hhAdminSearch" placeholder="Search households..." oninput="filterAdminHH()" style="margin-bottom:6px;font-size:.72rem"><div style="display:flex;gap:4px;margin-bottom:6px"><button class="hh-btn hh-btn-primary" onclick="createNewHousehold()" style="flex:1"><i class="fas fa-plus me-1"></i>New</button><select class="sbox" id="hhAdminFilter" style="width:auto;padding:3px 8px;font-size:.68rem" onchange="filterAdminHH()"><option value="">All</option><option value="family">Family</option><option value="couple">Couple</option><option value="individual">Individual</option></select></div><div id="hhAdminList"></div></div><div style="flex:1.8;overflow-y:auto"><div id="hhAdminEditor"><div class="lin-empty"><i class="fas fa-arrow-left me-1"></i>Select a household to edit</div></div></div></div><div style="border-top:1px solid var(--line);padding:6px 14px;display:flex;justify-content:space-between;align-items:center;font-size:.68rem"><span id="hhChangeCount" style="color:var(--muted)">No unsaved changes</span><span id="hhLastSaved" style="color:var(--dim)"></span></div></div></div><!-- ΓòÉΓòÉΓòÉ LINEAGE MODAL ΓòÉΓòÉΓòÉ --><div class="modal-overlay" id="lineageModal"><div class="modal-box"><div class="modal-hdr"><h5 id="lineageTitle"><i class="fas fa-code-branch me-1"></i>Data Lineage</h5><button class="modal-close" onclick="closeModal('lineageModal')">&times;</button></div><div class="modal-body" id="lineageBody"></div></div></div><!-- ΓòÉΓòÉΓòÉ EDIT MODAL ΓòÉΓòÉΓòÉ --><div class="modal-overlay" id="editModal"><div class="modal-box" style="max-width:500px"><div class="modal-hdr"><h5 id="editTitle"><i class="fas fa-pen me-1"></i>Edit Field</h5><button class="modal-close" onclick="closeModal('editModal')">&times;</button></div><div class="modal-body" id="editBody"></div></div></div><!-- ΓòÉΓòÉΓòÉ RELATIONSHIP ADMIN MODAL ΓòÉΓòÉΓòÉ --><div class="modal-overlay" id="relAdminModal"><div class="modal-box" style="max-width:1000px;height:88vh"><div class="modal-hdr"><h5><i class="fas fa-heart me-1"></i>Relationship Manager</h5><div style="display:flex;gap:6px;align-items:center"><span id="relChangeCount" style="font-size:.68rem;color:var(--muted)"></span><button class="hh-btn hh-btn-primary" onclick="saveRelChanges()"><i class="fas fa-save me-1"></i>Save</button><button class="modal-close" onclick="closeModal('relAdminModal')">&times;</button></div></div><div class="modal-body" style="display:flex;gap:12px;height:calc(100% - 60px);padding:10px"><!-- Left: member search --><div style="flex:1;min-width:280px;overflow-y:auto;border-right:1px solid var(--line);padding-right:10px"><input class="sbox" id="relAdminSearch" placeholder="Search member to manage..." oninput="relAdminSearchFn()" style="font-size:.72rem;margin-bottom:4px"><div style="display:flex;gap:4px;margin-bottom:6px"><select class="sbox" id="relAdminFilter" style="width:auto;padding:3px 8px;font-size:.68rem" onchange="relAdminSearchFn()"><option value="">All Members</option><option value="has_rel">Has Relationships</option><option value="no_rel">No Relationships</option><option value="ambiguous">Ambiguous Names</option></select></div><div id="relAdminMemberList" style="max-height:calc(100% - 80px);overflow-y:auto"></div></div><!-- Right: relationship editor --><div style="flex:2;overflow-y:auto"><div id="relAdminEditor"><div class="lin-empty"><i class="fas fa-arrow-left me-1"></i>Select a member to manage relationships</div></div></div></div></div></div><script>// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// BANF CRM ΓÇö Data Lineage, Admin Edit & Approval System// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉvar BASE='https://banfwix.wixsite.com/banf1/_functions';var ML=${lineageJSON};var ECR=${ecRosterJSON};// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// RELATIONSHIP DATA// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉvar REL_DATA=${relJSON};var REL_TYPES=${relTypesJSON};var REL_CHANGES=[];var REL_DIRTY=false;// Label ΓåÆ field mappingvar L2F={'First Name':'firstName','Last Name':'lastName','Email':'email','Phone':'phone','Phone 2':'phone2','Gender':'gender','DOB':'dateOfBirth','Address':'address','City/State':'city','Profession':'profession','Employer':'employer','Education':'education','Member ID':'memberId','Household ID':'householdId','Type':'householdType','Display Name':'householdDisplayName','Role':'householdRole','Spouse':'householdMembers','Kids (inferred)':'inferredKids','Membership':'householdMembershipCategory','Years':'householdYearActive','Network ID':'familyId','Members':'familyMembers','Member Since':'memberSince','Member Type':'memberType','Years Active':'membershipYears','Types':'membershipTypes','EC Member':'isECMember','Active':'isActive','Total':'communications'};// Permission tiers per fieldvar TIERS={firstName:'basic',lastName:'basic',displayName:'basic',phone:'basic',phone2:'basic',address:'basic',city:'basic',state:'basic',zip:'basic',gender:'basic',dateOfBirth:'basic',profession:'basic',employer:'basic',education:'basic',householdDisplayName:'basic',householdType:'readonly',householdId:'readonly',householdRole:'readonly',householdMembers:'readonly',inferredKids:'readonly',familyDisplayName:'readonly',familyType:'readonly',familyId:'readonly',familyMembers:'readonly',email:'readonly',memberId:'readonly',memberSince:'restricted',memberType:'restricted',membershipYears:'restricted',membershipTypes:'restricted',isECMember:'restricted',isActive:'restricted',communications:'restricted'};var session=null;// ΓöÇΓöÇΓöÇ Modal helpers ΓöÇΓöÇΓöÇfunction closeModal(id){document.getElementById(id).style.display='none'}function showAuthModal(){document.getElementById('authModal').style.display='flex';document.getElementById('authEmail').focus()}// ΓöÇΓöÇΓöÇ Auth ΓöÇΓöÇΓöÇfunction doLogin(){  var email=document.getElementById('authEmail').value.trim();  var pass=document.getElementById('authPass').value;  var msg=document.getElementById('authMsg');  if(!email){msg.innerHTML='<span style="color:var(--red)">Enter email</span>';return}  msg.innerHTML='<span style="color:var(--muted)">Verifying...</span>';  fetch(BASE+'/admin_verify_login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:email,password:pass})})  .then(function(r){return r.json()}).then(function(d){    if(d.success){      session={email:email.toLowerCase(),role:d.role||'admin',ecTitle:d.ecTitle||'',name:d.name||d.firstName||email};      closeModal('authModal');updateAuthBar();enhanceDOMForEdit();    } else {      // Fallback: check EC roster      var ecm=ECR.find(function(r){return r.email===email.toLowerCase()});      if(ecm){session={email:email.toLowerCase(),role:'admin',ecTitle:ecm.title,name:ecm.name};closeModal('authModal');updateAuthBar();enhanceDOMForEdit()}      else{msg.innerHTML='<span style="color:var(--red)">'+(d.error||'Login failed')+'</span>'}    }  }).catch(function(e){    var ecm=ECR.find(function(r){return r.email===email.toLowerCase()});    if(ecm){session={email:email.toLowerCase(),role:'admin',ecTitle:ecm.title,name:ecm.name};closeModal('authModal');updateAuthBar();enhanceDOMForEdit()}    else{msg.innerHTML='<span style="color:var(--red)">Auth error: '+e.message+'</span>'}  });}function updateAuthBar(){  var bar=document.getElementById('authBar');  if(session){    var ap=isApprover();    bar.innerHTML='<span class="aname"><i class="fas fa-user-shield me-1"></i>'+session.name+'</span>'      +'<span class="arole">'+session.ecTitle+(session.ecTitle?' ':'')+'('+session.role+')</span>'      +(ap?'<span class="tier-badge tier-restricted">Full Edit + Approve</span>':'<span class="tier-badge tier-basic">Basic Edit</span>')      +'<button class="abtn" onclick="doLogout()" style="background:var(--red);margin-left:8px"><i class="fas fa-right-from-bracket me-1"></i>Logout</button>';  } else {    bar.innerHTML='<button class="abtn" onclick="showAuthModal()"><i class="fas fa-lock me-1"></i>Admin Login</button>';  }}function doLogout(){session=null;updateAuthBar();document.querySelectorAll('.fv-edit,.fv-restricted').forEach(function(el){el.remove()})}function isApprover(){  if(!session) return false;  var t=(session.ecTitle||'').toLowerCase();  return t.indexOf('president')>=0||t.indexOf('vice president')>=0||t.indexOf('treasurer')>=0||session.role==='super_admin';}function canEdit(fn){  if(!session) return false;  var tier=TIERS[fn]||'basic';  if(tier==='readonly') return false;  if(tier==='basic') return true;  if(tier==='restricted') return isApprover();  return false;}// ΓöÇΓöÇΓöÇ Source badge helper ΓöÇΓöÇΓöÇfunction getSrcBadge(s){  if(!s) return 'other';  if(s.indexOf('crm')>=0&&s.indexOf('comprehensive')<0) return 'crm';  if(s.indexOf('google')>=0) return 'google';  if(s.indexOf('family')>=0) return 'family';  if(s.indexOf('membership')>=0||s.indexOf('2526')>=0) return 'member';  if(s.indexOf('audit')>=0) return 'audit';  if(s.indexOf('jagriti')>=0) return 'jagriti';  if(s.indexOf('admin')>=0) return 'admin';  if(s==='events'||s.indexOf('evite')>=0||s.indexOf('xlsx_evite')>=0) return 'event';  return 'other';}function srcBadge(s){return '<span class="badge b-'+getSrcBadge(s)+'">'+s+'</span>'}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// DATA LINEAGE POPUP// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉfunction showLineage(mi,fieldName,section){  var m=ML[mi]; if(!m) return;  document.getElementById('lineageTitle').innerHTML='<i class="fas fa-code-branch me-1"></i>Data Lineage: '+m.n+' &mdash; <em>'+fieldName+'</em>';  var h='';  // Sources overview  h+='<div class="lin-section"><h6><i class="fas fa-layer-group me-1"></i>Data Sources ('+m.src.length+')</h6>';  h+='<div style="display:flex;flex-wrap:wrap;gap:4px;margin-bottom:8px">';  m.src.forEach(function(s){h+=srcBadge(s)});  h+='</div></div>';  // ΓöÇΓöÇΓöÇ Personal field lineage ΓöÇΓöÇΓöÇ  if(section==='personal'){    var evts=m.rp.filter(function(r){return r.field===fieldName});    if(evts.length>0){      h+='<div class="lin-section"><h6><i class="fas fa-code-branch me-1"></i>Reconciliation Steps ('+evts.length+')</h6><div class="lin-tree">';      evts.forEach(function(evt,j){        var icon=evt.action==='set'?'\\u2705':'\\u26A0\\uFE0F';        var cls=evt.action==='set'?'lin-set':'lin-conflict';        h+='<div class="lin-step '+cls+'"><span class="lin-icon">'+icon+'</span><div class="lin-detail">'          +'<div class="lin-action">Step '+(j+1)+': '+evt.action.toUpperCase()+'</div>'          +'<div class="lin-val">Value: <strong>'+(evt.value||evt.newValue||'\\u2014')+'</strong></div>'          +(evt.oldValue?'<div class="lin-old">Previous: <span style="text-decoration:line-through">'+evt.oldValue+'</span></div>':'')          +'<div class="lin-src">Source: '+srcBadge(evt.source)+'</div>'          +'</div></div>';      });      h+='</div></div>';    } else {      h+='<div class="lin-empty"><i class="fas fa-info-circle me-1"></i>No multi-source reconciliation for <strong>'+fieldName+'</strong>. Value from primary source only.</div>';    }  }  // ΓöÇΓöÇΓöÇ Household unit ΓöÇΓöÇΓöÇ  if(section==='household'){    var hh=m.hh;    if(hh&&hh.id){      h+='<div class="lin-section"><h6><i class="fas fa-home me-1"></i>Household Unit (Membership Unit)</h6>';      h+='<div class="lin-tree"><div class="lin-step lin-set"><span class="lin-icon">\\uD83C\\uDFE0</span><div class="lin-detail">'        +'<div class="lin-action">Household: <strong>'+hh.name+'</strong></div>'        +'<div class="lin-val">Type: '+hh.type+' | Role: '+hh.role+(hh.spouse?' | Spouse: '+hh.spouse:'')+'</div>'        +(hh.kids>0?'<div class="lin-val">Kids (inferred from events): '+hh.kids+'</div>':'')        +'</div></div>';      if(hh.evidence&&hh.evidence.length>0){        h+='<div style="margin-top:6px"><strong style="font-size:.7rem;color:var(--green)">Spouse Evidence:</strong><br>';        hh.evidence.forEach(function(ev){          h+='<div class="lin-step lin-set" style="margin-left:10px"><span class="lin-icon">\\uD83D\\uDC8D</span><div class="lin-detail">'            +'<div class="lin-val">'+ev.type.replace(/_/g,' ')+': '+(ev.detail||'')+'</div></div></div>';        });        h+='</div>';      }      h+='</div><div style="margin-top:8px;font-size:.68rem;color:var(--muted)"><i class="fas fa-info-circle me-1"></i>'        +'<strong>Household vs Network:</strong> A household is the membership billing unit (max 2 adults + dependents under 21). '        +'The family network shows broader relationships (siblings, parents, extended family).</div></div>';    }  }  // ΓöÇΓöÇΓöÇ Family network assignment ΓöÇΓöÇΓöÇ  if(section==='family'){    var fEvts=m.rf;    if(fEvts.length>0){      h+='<div class="lin-section"><h6><i class="fas fa-people-roof me-1"></i>Family Network Assignment</h6><div class="lin-tree">';      fEvts.forEach(function(evt){        h+='<div class="lin-step lin-set"><span class="lin-icon">\\uD83C\\uDFE0</span><div class="lin-detail">'          +'<div class="lin-action">'+evt.source+'</div>'          +'<div class="lin-val">Network: <strong>'+evt.displayName+'</strong> ('+evt.type+', '+evt.members+' members, max 6)</div>'          +'<div class="lin-src">Evidence: '+evt.evidence+' edges, total weight: '+evt.totalWeight+'</div>'          +'</div></div>';      });      h+='</div></div>';    }  }  // ΓöÇΓöÇΓöÇ Membership history ΓöÇΓöÇΓöÇ  if(section==='membership'){    var mEvts=m.rm;    if(mEvts.length>0){      h+='<div class="lin-section"><h6><i class="fas fa-id-card me-1"></i>Membership History ('+mEvts.length+' records)</h6><div class="lin-tree">';      mEvts.forEach(function(evt){        h+='<div class="lin-step lin-set"><span class="lin-icon">\\uD83D\\uDCCB</span><div class="lin-detail">'          +'<div class="lin-val">'+(evt.year||'')+' &mdash; '+(evt.type||'\\u2014')+'</div>'          +'<div class="lin-src">Source: '+srcBadge(evt.source)+'</div>'          +'</div></div>';      });      h+='</div></div>';    }  }  // ΓöÇΓöÇΓöÇ Payment calculation ΓöÇΓöÇΓöÇ  if(fieldName==='totalPaid'||section==='payment'){    h+='<div class="lin-section"><h6><i class="fas fa-calculator me-1"></i>Payment Calculation Breakdown</h6>';    if(m.pr.length>0){      h+='<div class="lin-calc">';      m.pr.forEach(function(p){        h+='<div class="lin-calc-row"><span>'+p.y+' &mdash; '+p.c+(p.r?' ('+p.r+')':'')+'</span><span style="color:var(--accent)">$'+p.a.toFixed(2)+' '+srcBadge(p.s)+'</span></div>';      });      h+='<div class="lin-calc-row lin-calc-total"><span>SUM ('+m.pr.length+' records)</span><span>$'+m.tp.toFixed(2)+'</span></div>';      h+='</div>';    } else { h+='<div class="lin-empty">No payment records</div>'; }    // Payment reconciliation data    var payEvts=m.rpay;    if(payEvts.length>0){      h+='<div style="margin-top:8px"><h6 style="color:var(--cyan);font-size:.7rem">Payment Source Trail</h6><div class="lin-tree">';      payEvts.forEach(function(evt){        h+='<div class="lin-step lin-set"><span class="lin-icon">\\uD83D\\uDCB3</span><div class="lin-detail">'          +'<div class="lin-val">'+(evt.year||'')+' '+(evt.category||'')+' $'+(evt.amount||0)+'</div>'          +'<div class="lin-src">Source: '+srcBadge(evt.source)+'</div>'          +'</div></div>';      });      h+='</div></div>';    }    h+='</div>';  }  // ΓöÇΓöÇΓöÇ Events breakdown ΓöÇΓöÇΓöÇ  if(section==='events'||fieldName==='eventAttendance'){    h+='<div class="lin-section"><h6><i class="fas fa-calendar-check me-1"></i>Event Attendance ('+m.ea.length+' records)</h6>';    if(m.ea.length>0){      h+='<div class="lin-tree">';      m.ea.forEach(function(evt){        var rc=evt.rv==='attending'||evt.rv==='Yes'?'var(--green)':evt.rv==='not_attending'?'var(--red)':'var(--yellow)';        h+='<div class="lin-step lin-set"><span class="lin-icon">\\uD83C\\uDFAB</span><div class="lin-detail">'          +'<div class="lin-val">'+evt.en+' &mdash; <span style="color:'+rc+'">'+evt.rv+'</span></div>'          +(evt.ad?'<div style="font-size:.68rem;color:var(--muted)">Adults: '+evt.ad+(evt.ki?', Kids: '+evt.ki:'')+(evt.am?', Amount: $'+evt.am:'')+(evt.d&&evt.d!=='unknown'?', Diet: '+evt.d:'')+'</div>':'')          +'<div class="lin-src">Source: '+srcBadge(evt.s)+'</div>'          +'</div></div>';      });      h+='</div>';    }    if(m.ve.length>0){      h+='<h6 style="margin-top:10px;color:var(--cyan);font-size:.7rem"><i class="fas fa-hand-holding-heart me-1"></i>Volunteer Roles ('+m.ve.length+')</h6><div class="lin-tree">';      m.ve.forEach(function(v){        h+='<div class="lin-step lin-set"><span class="lin-icon">\\uD83E\\uDD1D</span><div class="lin-detail">'          +'<div class="lin-val">'+v.en+' &mdash; '+v.ro+'</div>'          +'<div class="lin-src">Source: '+srcBadge(v.s)+'</div></div></div>';      });      h+='</div>';    }    h+='</div>';  }  // ΓöÇΓöÇΓöÇ Cultural/Jagriti ΓöÇΓöÇΓöÇ  if(section==='cultural'||fieldName==='jagriti'){    h+='<div class="lin-section"><h6><i class="fas fa-book me-1"></i>Cultural Contributions ('+m.jc.length+')</h6>';    if(m.jc.length>0){      h+='<div class="lin-tree">';      m.jc.forEach(function(j){        h+='<div class="lin-step lin-set"><span class="lin-icon">\\uD83C\\uDFAD</span><div class="lin-detail">'          +'<div class="lin-val">Jagriti '+j.y+': '+j.t+(j.c>1?' x'+j.c:'')+'</div>'          +(j.cm?'<div style="font-size:.68rem;color:var(--muted)">'+j.cm+'</div>':'')          +'<div class="lin-src">Source: '+srcBadge(j.s)+'</div></div></div>';      });      h+='</div>';    }    h+='</div>';  }  // ΓöÇΓöÇΓöÇ Org roles ΓöÇΓöÇΓöÇ  if(section==='orgRole'||fieldName==='orgRoles'){    h+='<div class="lin-section"><h6><i class="fas fa-id-badge me-1"></i>Organization Roles ('+m.or.length+')</h6>';    if(m.or.length>0){      h+='<div class="lin-tree">';      m.or.forEach(function(r){        h+='<div class="lin-step lin-set"><span class="lin-icon">\\uD83D\\uDC54</span><div class="lin-detail">'          +'<div class="lin-val">'+r.t+': <strong>'+r.ro+'</strong></div>'          +'<div class="lin-src">Source: '+srcBadge(r.s)+'</div></div></div>';      });      h+='</div>';    }    h+='</div>';  }  // ΓöÇΓöÇΓöÇ Communications ΓöÇΓöÇΓöÇ  if(section==='communication'){    h+='<div class="lin-section"><h6><i class="fas fa-envelope me-1"></i>Communications</h6>';    var cEvts=m.rco;    if(cEvts.length>0){      h+='<div class="lin-tree">';      cEvts.forEach(function(evt){        h+='<div class="lin-step lin-set"><span class="lin-icon">\\uD83D\\uDCE7</span><div class="lin-detail">'          +'<div class="lin-val">Count: '+(evt.count||0)+'</div>'          +'<div class="lin-src">Source: '+srcBadge(evt.source)+'</div></div></div>';      });      h+='</div>';    }    h+='</div>';  }  // ΓöÇΓöÇΓöÇ Issues ΓöÇΓöÇΓöÇ  if(m.iss.length>0){    h+='<div class="lin-section"><h6><i class="fas fa-triangle-exclamation me-1"></i>Data Quality Issues ('+m.iss.length+')</h6>';    m.iss.forEach(function(is){      var ic=is.severity==='error'?'\\uD83D\\uDD34':is.severity==='warning'?'\\uD83D\\uDFE1':'\\uD83D\\uDD35';      h+='<div style="font-size:.72rem;padding:2px 0">'+ic+' ['+is.area+'] '+is.msg+'</div>';    });    h+='</div>';  }  document.getElementById('lineageBody').innerHTML=h;  document.getElementById('lineageModal').style.display='flex';}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// FAMILY ADMIN EDITOR ΓÇö Manage Households// Active data + historical change tracking + localStorage persistence// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉvar HH_DATA=null,HH_CHANGES=[],HH_DIRTY=false;function initHouseholdAdmin(){  HH_DATA={};  ML.forEach(function(m){    if(!m.hh||!m.hh.id) return;    if(!HH_DATA[m.hh.id]) HH_DATA[m.hh.id]={id:m.hh.id,type:m.hh.type,name:m.hh.name,members:[],cat:m.hh.cat||'',amt:m.hh.amt||0,raw:m.hh.raw||'',years:m.hh.years||[],updated:m.hh.updated||'',notes:''};    HH_DATA[m.hh.id].members.push({email:m.e,name:m.n,role:m.hh.role});  });  var saved=localStorage.getItem('banf_household_overrides');  if(saved){try{var ov=JSON.parse(saved);if(ov.households){for(var k in ov.households)if(HH_DATA[k])Object.assign(HH_DATA[k],ov.households[k])}HH_CHANGES=ov.changeLog||[];document.getElementById('hhLastSaved').textContent='Last saved: '+(ov.lastSaved||'unknown')}catch(e){}}}function openFamilyAdmin(){  if(!session){showAuthModal();return}  initHouseholdAdmin();renderHHList();  document.getElementById('familyAdminModal').style.display='flex';}function renderHHList(){  var el=document.getElementById('hhAdminList');  var q=(document.getElementById('hhAdminSearch')?.value||'').toLowerCase();  var tf=document.getElementById('hhAdminFilter')?.value||'';  var sorted=Object.values(HH_DATA).sort(function(a,b){if(a.type==='individual'&&b.type!=='individual')return 1;if(a.type!=='individual'&&b.type==='individual')return -1;return a.name.localeCompare(b.name)});  var html='',counts={family:0,couple:0,individual:0};  for(var i=0;i<sorted.length;i++){    var hh=sorted[i]; counts[hh.type]=(counts[hh.type]||0)+1;    var st=(hh.name+' '+hh.members.map(function(m){return m.name+' '+m.email}).join(' ')).toLowerCase();    if(q&&st.indexOf(q)<0) continue;    if(tf&&hh.type!==tf) continue;    var ic=hh.type==='family'?'house':hh.type==='couple'?'heart':'user';    var tcol=hh.type==='individual'?'var(--dim)':'var(--green)';    html+='<div class="hh-admin-card" data-hhid="'+hh.id+'" onclick="editHH(\''+hh.id+'\')">'      +'<div style="display:flex;justify-content:space-between"><div><i class="fas fa-'+ic+' me-1" style="color:'+tcol+'"></i><strong style="font-size:.75rem">'+hh.name+'</strong> <span class="badge b-family" style="font-size:.5rem">'+hh.type+'</span></div><span style="font-size:.55rem;color:var(--dim)">'+hh.id+'</span></div>'      +'<div style="font-size:.65rem;color:var(--muted);margin-top:2px">'+hh.members.map(function(m){return m.name}).join(', ')+'</div>'      +(hh.cat?'<div style="font-size:.58rem;color:var(--accent);margin-top:1px">'+hh.cat+(hh.amt?' $'+hh.amt:'')+'</div>':'')      +'</div>';  }  el.innerHTML=html||'<div class="lin-empty">No households</div>';}function editHH(hhId){  var hh=HH_DATA[hhId]; if(!hh) return;  document.querySelectorAll('.hh-admin-card').forEach(function(c){c.classList.remove('selected')});  var s=document.querySelector('.hh-admin-card[data-hhid="'+hhId+'"]'); if(s)s.classList.add('selected');  var h='<h6 style="color:var(--accent);margin-bottom:8px"><i class="fas fa-pen me-1"></i>'+hh.name+'</h6>';  h+='<div style="margin-bottom:8px"><label style="font-size:.68rem;color:var(--muted)">Type</label><br><select class="sbox" style="width:auto;display:inline;padding:4px 8px;font-size:.75rem" onchange="chgHHType(\''+hhId+'\',this.value)">';  ['family','couple','individual'].forEach(function(t){h+='<option value="'+t+'"'+(hh.type===t?' selected':'')+'>'+t.charAt(0).toUpperCase()+t.slice(1)+'</option>'});  h+='</select></div>';  h+='<div style="margin-bottom:8px"><label style="font-size:.68rem;color:var(--muted)">Members ('+hh.members.length+')</label>';  hh.members.forEach(function(m){    h+='<div class="hh-member-chip"><span>'+m.name+'</span>';    h+=' <select style="font-size:.58rem;background:transparent;border:none;color:var(--muted);cursor:pointer" onchange="chgRole(\''+hhId+'\',\''+m.email+'\',this.value)">';    ['primary','spouse','child','sibling','parent','other'].forEach(function(r){h+='<option value="'+r+'"'+(m.role===r?' selected':'')+'>'+r+'</option>'});    h+='</select>';    if(hh.members.length>1) h+=' <span class="remove" onclick="rmFromHH(\''+hhId+'\',\''+m.email+'\')"><i class="fas fa-times"></i></span>';    h+='</div>';  });  h+='</div>';  h+='<div style="margin-bottom:8px"><label style="font-size:.68rem;color:var(--muted)">Add Member</label>';  h+='<input class="sbox" id="hhAddQ" placeholder="Search name or email..." oninput="searchForHH(\''+hhId+'\')" style="margin-bottom:3px;font-size:.72rem">';  h+='<div id="hhAddRes" style="max-height:120px;overflow-y:auto"></div></div>';  if(hh.cat){    h+='<div style="margin-bottom:8px;background:var(--bg);border:1px solid var(--line);border-radius:6px;padding:6px">';    h+='<label style="font-size:.68rem;color:var(--muted)">Membership</label>';    h+='<div style="font-size:.72rem"><strong style="color:var(--accent)">'+hh.cat+'</strong>'+(hh.amt?' ΓÇö $'+hh.amt:'')+'</div>';    if(hh.raw) h+='<div style="font-size:.65rem;color:var(--dim)">XLSX: "'+hh.raw+'"</div>';    h+='</div>';  }  h+='<div style="margin-bottom:8px"><label style="font-size:.68rem;color:var(--muted)">Years Active</label><div>'+(hh.years||[]).map(function(y){return '<span class="b-year">'+y+'</span>'}).join(' ')+'</div></div>';  h+='<div style="margin-bottom:8px"><label style="font-size:.68rem;color:var(--muted)">Notes</label>';  h+='<textarea class="sbox" rows="2" style="font-size:.72rem" onchange="updNotes(\''+hhId+'\',this.value)">'+(hh.notes||'')+'</textarea></div>';  h+='<div style="font-size:.62rem;color:var(--dim);margin-bottom:8px">Last Updated: '+(hh.updated||'never')+'</div>';  h+='<div style="display:flex;gap:6px"><button class="hh-btn hh-btn-danger" onclick="delHH(\''+hhId+'\')"><i class="fas fa-trash me-1"></i>Delete</button>';  h+='<button class="hh-btn" onclick="splitHH(\''+hhId+'\')"><i class="fas fa-code-branch me-1"></i>Split</button></div>';  var hcl=HH_CHANGES.filter(function(c){return c.hhId===hhId});  if(hcl.length>0){h+='<div style="margin-top:10px"><label style="font-size:.68rem;color:var(--muted)">Change History</label><div class="hh-change-log">';hcl.forEach(function(c){h+='<div class="entry">'+c.ts+' ΓÇö '+c.act+(c.d?': '+c.d:'')+'</div>'});h+='</div></div>'}  document.getElementById('hhAdminEditor').innerHTML=h;}function searchForHH(hhId){  var q=(document.getElementById('hhAddQ')?.value||'').toLowerCase();  var el=document.getElementById('hhAddRes');  if(!q||q.length<2){el.innerHTML='';return}  var hh=HH_DATA[hhId],existing=new Set(hh.members.map(function(m){return m.email}));  var res=ML.filter(function(m){if(existing.has(m.e))return false;return m.n.toLowerCase().indexOf(q)>=0||m.e.toLowerCase().indexOf(q)>=0}).slice(0,8);  el.innerHTML=res.map(function(m){return '<div style="padding:3px 6px;font-size:.7rem;cursor:pointer;border-bottom:1px solid var(--line)" onclick="addToHH(\''+hhId+'\',\''+m.e+'\',\''+m.n.replace(/'/g,"\\'")+'\')">'    +'<strong>'+m.n+'</strong> <span style="color:var(--dim);font-size:.6rem">'+m.e+'</span> <span style="color:var(--green);font-size:.58rem"><i class="fas fa-plus"></i></span></div>'}).join('')||'<div style="font-size:.65rem;color:var(--dim);padding:3px">No results</div>';}function addToHH(hhId,email,name){  var hh=HH_DATA[hhId]; if(!hh) return;  for(var id in HH_DATA){var old=HH_DATA[id];var idx=old.members.findIndex(function(m){return m.email===email});    if(idx>=0){old.members.splice(idx,1);logCh(id,'remove',name+' moved out');if(old.members.length===0){delete HH_DATA[id];logCh(id,'delete','Empty')}break}}  hh.members.push({email:email,name:name,role:hh.members.length===0?'primary':'spouse'});  hh.updated=new Date().toISOString();logCh(hhId,'add_member',name+' added');  HH_DIRTY=true;updChg();renderHHList();editHH(hhId);}function rmFromHH(hhId,email){  var hh=HH_DATA[hhId]; if(!hh) return;  var m=hh.members.find(function(m){return m.email===email}); if(!m) return;  hh.members=hh.members.filter(function(m){return m.email!==email});  hh.updated=new Date().toISOString();logCh(hhId,'remove',m.name+' removed');  var nid='HH-A-'+Date.now();  HH_DATA[nid]={id:nid,type:'individual',name:m.name,members:[{email:email,name:m.name,role:'primary'}],cat:'',amt:0,raw:'',years:[],updated:new Date().toISOString(),notes:'Split from '+hhId};  logCh(nid,'create','From split');  if(hh.members.length===0){delete HH_DATA[hhId];logCh(hhId,'delete','Empty')}  HH_DIRTY=true;updChg();renderHHList();  if(HH_DATA[hhId])editHH(hhId);else document.getElementById('hhAdminEditor').innerHTML='<div class="lin-empty">Deleted</div>';}function chgHHType(hhId,t){var hh=HH_DATA[hhId];if(!hh)return;logCh(hhId,'type',hh.type+' ΓåÆ '+t);hh.type=t;hh.updated=new Date().toISOString();HH_DIRTY=true;updChg();renderHHList()}function chgRole(hhId,email,r){var hh=HH_DATA[hhId];if(!hh)return;var m=hh.members.find(function(m){return m.email===email});if(m){logCh(hhId,'role',m.name+': '+m.role+' ΓåÆ '+r);m.role=r;hh.updated=new Date().toISOString();HH_DIRTY=true;updChg()}}function updNotes(hhId,n){var hh=HH_DATA[hhId];if(!hh)return;hh.notes=n;hh.updated=new Date().toISOString();HH_DIRTY=true;updChg()}function createNewHousehold(){  var nid='HH-A-'+Date.now();  HH_DATA[nid]={id:nid,type:'individual',name:'New Household',members:[],cat:'',amt:0,raw:'',years:['2025-26'],updated:new Date().toISOString(),notes:'Created by admin'};  logCh(nid,'create','New household');HH_DIRTY=true;updChg();renderHHList();editHH(nid);}function delHH(hhId){  var hh=HH_DATA[hhId]; if(!hh) return;  if(!confirm('Delete "'+hh.name+'"? Members become individual households.')) return;  hh.members.forEach(function(m){var nid='HH-A-'+Date.now()+'-'+Math.random().toString(36).substr(2,4);    HH_DATA[nid]={id:nid,type:'individual',name:m.name,members:[{email:m.email,name:m.name,role:'primary'}],cat:'',amt:0,raw:'',years:[],updated:new Date().toISOString(),notes:'From deleted '+hhId}});  logCh(hhId,'delete',hh.name+' deleted');delete HH_DATA[hhId];  HH_DIRTY=true;updChg();renderHHList();document.getElementById('hhAdminEditor').innerHTML='<div class="lin-empty">Deleted</div>';}function splitHH(hhId){var hh=HH_DATA[hhId];if(!hh||hh.members.length<2){alert('Nothing to split');return}if(confirm('Split into individual households?'))delHH(hhId)}function logCh(hhId,act,d){HH_CHANGES.push({ts:new Date().toISOString().slice(0,19).replace('T',' '),hhId:hhId,act:act,d:d,by:session?session.email:'?'})}function updChg(){var el=document.getElementById('hhChangeCount');el.innerHTML=HH_DIRTY?'<span style="color:var(--yellow)"><i class="fas fa-exclamation-circle me-1"></i>'+HH_CHANGES.length+' changes (unsaved)</span>':'No unsaved changes'}function saveHouseholdChanges(){  localStorage.setItem('banf_household_overrides',JSON.stringify({version:1,lastSaved:new Date().toISOString(),savedBy:session?session.email:'?',households:HH_DATA,changeLog:HH_CHANGES}));  HH_DIRTY=false;updChg();document.getElementById('hhLastSaved').textContent='Saved: '+new Date().toLocaleString();  alert('Saved to browser storage.\\nUse Export to create a portable JSON file.');}function exportHouseholdJSON(){  var d={version:1,exported:new Date().toISOString(),exportedBy:session?session.email:'?',households:HH_DATA,changeLog:HH_CHANGES,    summary:{total:Object.keys(HH_DATA).length,families:Object.values(HH_DATA).filter(function(h){return h.type==='family'}).length,      couples:Object.values(HH_DATA).filter(function(h){return h.type==='couple'}).length,      individuals:Object.values(HH_DATA).filter(function(h){return h.type==='individual'}).length}};  var b=new Blob([JSON.stringify(d,null,2)],{type:'application/json'});  var a=document.createElement('a');a.href=URL.createObjectURL(b);  a.download='banf-households-'+new Date().toISOString().slice(0,10)+'.json';  document.body.appendChild(a);a.click();document.body.removeChild(a);}function importHouseholdJSON(){  var inp=document.createElement('input');inp.type='file';inp.accept='.json';  inp.onchange=function(e){var f=e.target.files[0];if(!f)return;var r=new FileReader();    r.onload=function(e){try{var d=JSON.parse(e.target.result);if(d.households){HH_DATA=d.households;HH_CHANGES=d.changeLog||[];HH_DIRTY=true;updChg();renderHHList();      alert('Imported '+Object.keys(HH_DATA).length+' households. Save to persist.')}}catch(err){alert('Invalid JSON: '+err.message)}};r.readAsText(f)};  inp.click();}function filterAdminHH(){renderHHList()}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// ADMIN EDIT SYSTEM// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉfunction showEdit(mi,fieldName,section){  if(!session){showAuthModal();return}  var m=ML[mi]; if(!m) return;  var tier=TIERS[fieldName]||'basic';  document.getElementById('editTitle').innerHTML='<i class="fas fa-pen me-1"></i>Edit: '+m.n+' &mdash; <em>'+fieldName+'</em> <span class="tier-badge tier-'+tier+'">'+tier+'</span>';  // Get current value from DOM  var detail=document.querySelector('.detail[data-member="'+mi+'"]');  var currentVal='';  if(detail){    var dg=detail.querySelector('.dg[data-section="'+section+'"]');    if(dg){      var labels=dg.querySelectorAll('.k');      var values=dg.querySelectorAll('.v');      for(var j=0;j<labels.length;j++){        var fn=L2F[labels[j].textContent.trim()];        if(fn===fieldName&&values[j]){currentVal=values[j].textContent.replace(/[\\u{1F50D}\\u270F\\u{1F512}]/gu,'').trim();break}      }    }  }  if(currentVal==='\\u2014'||currentVal==='ΓÇö') currentVal='';  var h='';  if(tier==='restricted'&&!isApprover()){    // Non-approver sees approval request form    h+='<div class="approval-banner"><div class="ab-title"><i class="fas fa-lock me-1"></i>Restricted Field ΓÇö Requires Approval</div>'      +'<div style="margin-top:4px">Changes to <strong>'+fieldName+'</strong> require approval from <strong>President, Vice President, and Treasurer</strong>.</div></div>';    h+='<div class="edit-form"><label>Current Value</label><input type="text" value="'+(currentVal||'')+'" disabled style="opacity:.6">'      +'<label>Proposed New Value</label><input type="text" id="editNewVal" placeholder="Enter new value...">'      +'<label>Reason for Change</label><textarea id="editReason" rows="2" placeholder="Why this change is needed..."></textarea>'      +'<div style="margin-top:10px"><button class="btn-request" onclick="submitApproval('+mi+",'"+ fieldName+"','"+section+"'"+ ')"><i class="fas fa-paper-plane me-1"></i>Request Approval</button>'      +'<button class="btn-cancel" onclick="closeModal(\\x27editModal\\x27)">Cancel</button></div></div>';  } else if(tier!=='readonly'){    // Direct edit    h+='<div class="edit-form"><label>Field</label><div style="font-size:.82rem;font-weight:700;color:var(--text);margin-bottom:8px">'+fieldName+'</div>'      +'<label>Current Value</label><input type="text" value="'+(currentVal||'')+'" disabled style="opacity:.6">'      +'<label>New Value</label><input type="text" id="editNewVal" value="'+(currentVal||'')+'">'      +'<div style="margin-top:10px"><button class="btn-save" onclick="saveEdit('+mi+",'"+ fieldName+"','"+section+"'"+ ')"><i class="fas fa-save me-1"></i>Save</button>'      +'<button class="btn-cancel" onclick="closeModal(\\x27editModal\\x27)">Cancel</button></div>'      +'<div id="editMsg" style="margin-top:8px;font-size:.72rem"></div></div>';  } else {    h+='<div class="lin-empty"><i class="fas fa-ban me-1"></i>This field is read-only and cannot be edited.</div>';  }  document.getElementById('editBody').innerHTML=h;  document.getElementById('editModal').style.display='flex';}function saveEdit(mi,fieldName,section){  var newVal=document.getElementById('editNewVal').value;  var msg=document.getElementById('editMsg');  var m=ML[mi];  if(!m){msg.innerHTML='<span style="color:var(--red)">Error</span>';return}  msg.innerHTML='<span style="color:var(--muted)"><i class="fas fa-spinner fa-spin me-1"></i>Saving...</span>';  var body={email:m.e};body[fieldName]=newVal;  fetch(BASE+'/crm_member_update',{method:'POST',headers:{'Content-Type':'application/json','x-user-email':session.email},body:JSON.stringify(body)})  .then(function(r){return r.json()}).then(function(d){    if(d.success){      msg.innerHTML='<span style="color:var(--green)"><i class="fas fa-check me-1"></i>Saved! Refresh to see updated data.</span>';      // Update DOM      var detail=document.querySelector('.detail[data-member="'+mi+'"]');      if(detail){        var dg=detail.querySelector('.dg[data-section="'+section+'"]');        if(dg){          var labels=dg.querySelectorAll('.k');var values=dg.querySelectorAll('.v');          for(var j=0;j<labels.length;j++){            if(L2F[labels[j].textContent.trim()]===fieldName&&values[j]){              var icons=values[j].querySelectorAll('.fv-icon');              values[j].textContent=newVal||'\\u2014';              icons.forEach(function(ic){values[j].appendChild(ic)});break            }          }        }      }    } else { msg.innerHTML='<span style="color:var(--red)">'+(d.error||'Save failed')+'</span>' }  }).catch(function(e){ msg.innerHTML='<span style="color:var(--red)">Network error: '+e.message+'</span>' });}function submitApproval(mi,fieldName,section){  var newVal=document.getElementById('editNewVal').value;  var reason=document.getElementById('editReason').value;  var m=ML[mi];  if(!newVal){alert('Enter a new value');return}  if(!reason){alert('Enter a reason for the change');return}  var approvers=ECR.filter(function(r){    var t=(r.title||'').toLowerCase();    return t.indexOf('president')>=0||t.indexOf('vice president')>=0||t.indexOf('treasurer')>=0;  });  var names=approvers.map(function(a){return a.name+' ('+a.email+')'}).join(', ');  // Send notification via API  fetch(BASE+'/crm_member_update',{method:'POST',headers:{'Content-Type':'application/json','x-user-email':session.email},    body:JSON.stringify({email:m.e,approvalRequest:true,field:fieldName,newValue:newVal,reason:reason,requestedBy:session.email})})  .then(function(r){return r.json()}).then(function(d){    alert('Approval request submitted!\\n\\nField: '+fieldName+'\\nNew Value: '+newVal+'\\nReason: '+reason+'\\n\\nApprovers: '+names+'\\n\\nThe edit will be applied once President, Vice President, and Treasurer all approve.');    closeModal('editModal');  }).catch(function(){    alert('Approval request created (offline).\\n\\nPlease notify: '+names);    closeModal('editModal');  });}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// DOM ENHANCEMENT ΓÇö Add lineage/edit icons to all fields// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉfunction enhanceDOM(){  document.querySelectorAll('.detail').forEach(function(det){    var mi=det.dataset.member; if(mi===undefined) return;    // Enhance structured fields in .dg grids    det.querySelectorAll('.dg').forEach(function(dg){      var section=dg.dataset.section; if(!section) return;      var labels=dg.querySelectorAll('.k');      var values=dg.querySelectorAll('.v');      for(var j=0;j<labels.length;j++){        var label=labels[j].textContent.trim();        var fieldName=L2F[label];        if(!fieldName||!values[j]||values[j].querySelector('.fv-icon')) continue;        var linIcon=document.createElement('span');        linIcon.className='fv-icon fv-lineage';linIcon.title='View data lineage for '+fieldName;        linIcon.innerHTML='<i class="fas fa-code-branch"></i>';        linIcon.setAttribute('data-mi',mi);linIcon.setAttribute('data-fn',fieldName);linIcon.setAttribute('data-sec',section);        linIcon.onclick=function(){showLineage(parseInt(this.dataset.mi),this.dataset.fn,this.dataset.sec)};        values[j].appendChild(linIcon);      }    });    // Enhance section headers (Payments, Events, Cultural, Org Roles, Communications)    det.querySelectorAll('.dsec').forEach(function(dsec){      var h6=dsec.querySelector('h6'); if(!h6||h6.querySelector('.fv-icon')) return;      var txt=h6.textContent;      var mapping=[        {match:'Household Unit',fn:'householdId',sec:'household'},        {match:'Family Network',fn:'familyId',sec:'family'},        {match:'Payments',fn:'totalPaid',sec:'payment'},        {match:'Events',fn:'eventAttendance',sec:'events'},        {match:'Cultural',fn:'jagriti',sec:'cultural'},        {match:'Org Roles',fn:'orgRoles',sec:'orgRole'},        {match:'Communications',fn:'communications',sec:'communication'}      ];      mapping.forEach(function(mp){        if(txt.indexOf(mp.match)>=0){          var icon=document.createElement('span');          icon.className='fv-icon fv-lineage';icon.title='View '+mp.match+' lineage';          icon.innerHTML=' <i class="fas fa-code-branch"></i>';          icon.setAttribute('data-mi',mi);icon.setAttribute('data-fn',mp.fn);icon.setAttribute('data-sec',mp.sec);          icon.onclick=function(){showLineage(parseInt(this.dataset.mi),this.dataset.fn,this.dataset.sec)};          h6.appendChild(icon);        }      });    });    // Enhance payment total calc icon    det.querySelectorAll('.calc-val').forEach(function(cv){      if(cv.querySelector('.fv-icon')) return;      var cmi=cv.dataset.m||mi;      var icon=document.createElement('span');      icon.className='fv-icon fv-lineage';icon.title='View calculation breakdown';      icon.innerHTML=' <i class="fas fa-calculator"></i>';      icon.setAttribute('data-mi',cmi);      icon.onclick=function(){showLineage(parseInt(this.dataset.mi),'totalPaid','payment')};      cv.appendChild(icon);    });  });}function enhanceDOMForEdit(){  if(!session) return;  document.querySelectorAll('.detail').forEach(function(det){    var mi=det.dataset.member; if(mi===undefined) return;    det.querySelectorAll('.dg').forEach(function(dg){      var section=dg.dataset.section; if(!section) return;      var labels=dg.querySelectorAll('.k');var values=dg.querySelectorAll('.v');      for(var j=0;j<labels.length;j++){        var label=labels[j].textContent.trim();        var fieldName=L2F[label];        if(!fieldName||!values[j]) continue;        var tier=TIERS[fieldName]||'basic';        if(tier==='readonly'||values[j].querySelector('.fv-edit,.fv-restricted')) continue;        if(canEdit(fieldName)){          var editIcon=document.createElement('span');          editIcon.className='fv-icon fv-edit';editIcon.title='Edit '+fieldName+' ('+tier+')';          editIcon.innerHTML='<i class="fas fa-pen-to-square"></i>';          editIcon.setAttribute('data-mi',mi);editIcon.setAttribute('data-fn',fieldName);editIcon.setAttribute('data-sec',section);          editIcon.onclick=function(){showEdit(parseInt(this.dataset.mi),this.dataset.fn,this.dataset.sec)};          values[j].appendChild(editIcon);        } else if(tier==='restricted'){          var reqIcon=document.createElement('span');          reqIcon.className='fv-icon fv-restricted';reqIcon.title='Request approval to edit '+fieldName;          reqIcon.innerHTML='<i class="fas fa-lock"></i>';          reqIcon.setAttr